{
  "name": "HotelFlow Invoice Pro",
  "description": "A sophisticated hotel invoice generation system with AI-powered personalized guest notes and automated billing calculations.",
  "requestFramePermissions": []
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface InvoiceItem {
  id: string;
  description: string;
  quantity: number;
  unitPrice: number;
  total: number;
}

export interface GuestInfo {
  name: string;
  email: string;
  phone: string;
  address: string;
}

export interface StayDetails {
  roomNumber: string;
  roomType: string;
  checkIn: string;
  checkOut: string;
  guestsCount: number;
}

export interface Invoice {
  id: string;
  invoiceNumber: string;
  date: string;
  guest: GuestInfo;
  stay: StayDetails;
  items: InvoiceItem[];
  taxRate: number;
  discount: number;
  status: 'draft' | 'paid' | 'cancelled';
  notes: string;
  aiGreeting?: string;
}

export type ViewMode = 'list' | 'create' | 'view';

import React from 'react';

export const HOTEL_INFO = {
  name: 'Azure Luxe Resort & Spa',
  address: '123 Ocean Drive, Bali, Indonesia 80361',
  phone: '+62 361 555 0123',
  email: 'concierge@azureluxe.com',
  website: 'www.azureluxe.com',
  logo: 'https://picsum.photos/id/43/200/200'
};

export const ROOM_TYPES = [
  'Deluxe Garden View',
  'Ocean Premier Suite',
  'Royal Presidential Villa',
  'Executive Studio',
  'Family connecting Suite'
];

export const TAX_RATE = 0.11; // 11% PPN Indonesia

import { GoogleGenAI } from "@google/genai";
import { Invoice } from "../types";

export const generatePersonalizedNote = async (invoice: Invoice): Promise<string> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });
    const prompt = `
      Act as a high-end luxury hotel concierge. 
      Generate a short, professional, and warm thank-you note for a guest stay.
      Guest Name: ${invoice.guest.name}
      Room Type: ${invoice.stay.roomType}
      Stay: From ${invoice.stay.checkIn} to ${invoice.stay.checkOut}
      Items billed include: ${invoice.items.map(i => i.description).join(', ')}

      The note should mention their specific room type and wish them a pleasant journey. 
      Keep it under 60 words. Language: Indonesian (Sopan/Formal).
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });

    return response.text || "Terima kasih telah menginap bersama kami. Kami berharap dapat menyambut Anda kembali.";
  } catch (error) {
    console.error("Gemini Error:", error);
    return "Terima kasih telah menginap di Azure Luxe Resort & Spa. Semoga perjalanan Anda menyenangkan.";
  }
};

import React from 'react';
import { InvoiceItem } from '../types';

interface Props {
  item: InvoiceItem;
  onUpdate: (id: string, updates: Partial<InvoiceItem>) => void;
  onDelete: (id: string) => void;
}

export const InvoiceItemRow: React.FC<Props> = ({ item, onUpdate, onDelete }) => {
  return (
    <div className="grid grid-cols-12 gap-4 items-center mb-3">
      <div className="col-span-6">
        <input
          type="text"
          value={item.description}
          onChange={(e) => onUpdate(item.id, { description: e.target.value })}
          placeholder="Service or Item Description"
          className="w-full px-3 py-2 border border-slate-200 rounded-lg focus:ring-2 focus:ring-indigo-500 outline-none"
        />
      </div>
      <div className="col-span-2">
        <input
          type="number"
          value={item.quantity}
          onChange={(e) => onUpdate(item.id, { quantity: Number(e.target.value) })}
          className="w-full px-3 py-2 border border-slate-200 rounded-lg focus:ring-2 focus:ring-indigo-500 outline-none text-center"
          min="1"
        />
      </div>
      <div className="col-span-2">
        <input
          type="number"
          value={item.unitPrice}
          onChange={(e) => onUpdate(item.id, { unitPrice: Number(e.target.value) })}
          className="w-full px-3 py-2 border border-slate-200 rounded-lg focus:ring-2 focus:ring-indigo-500 outline-none text-right"
        />
      </div>
      <div className="col-span-1 text-right font-medium text-slate-700">
        ${(item.quantity * item.unitPrice).toLocaleString()}
      </div>
      <div className="col-span-1 text-right">
        <button
          onClick={() => onDelete(item.id)}
          className="text-red-400 hover:text-red-600 p-1"
        >
          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
          </svg>
        </button>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useCallback } from 'react';
import { Invoice, ViewMode, InvoiceItem } from './types';
import { InvoicePreview } from './components/InvoicePreview';
import { InvoiceItemRow } from './components/InvoiceItemRow';
import { ROOM_TYPES, TAX_RATE } from './constants';
import { generatePersonalizedNote } from './services/geminiService';

const INITIAL_GUEST = { name: '', email: '', phone: '', address: '' };
const INITIAL_STAY = { roomNumber: '', roomType: ROOM_TYPES[0], checkIn: '', checkOut: '', guestsCount: 1 };

const App: React.FC = () => {
  const [viewMode, setViewMode] = useState<ViewMode>('list');
  const [invoices, setInvoices] = useState<Invoice[]>([]);
  const [currentInvoice, setCurrentInvoice] = useState<Invoice | null>(null);
  const [isGeneratingNote, setIsGeneratingNote] = useState(false);

  // Load from local storage
  useEffect(() => {
    const saved = localStorage.getItem('hotelflow_invoices');
    if (saved) {
      setInvoices(JSON.parse(saved));
    }
  }, []);

  // Save to local storage
  useEffect(() => {
    localStorage.setItem('hotelflow_invoices', JSON.stringify(invoices));
  }, [invoices]);

  const createNewInvoice = () => {
    const id = Math.random().toString(36).substr(2, 9);
    const newInvoice: Invoice = {
      id,
      invoiceNumber: `INV-${new Date().getFullYear()}-${Math.floor(Math.random() * 9000 + 1000)}`,
      date: new Date().toISOString().split('T')[0],
      guest: { ...INITIAL_GUEST },
      stay: { ...INITIAL_STAY },
      items: [
        { id: '1', description: 'Room Accommodation', quantity: 1, unitPrice: 0, total: 0 }
      ],
      taxRate: TAX_RATE,
      discount: 0,
      status: 'draft',
      notes: ''
    };
    setCurrentInvoice(newInvoice);
    setViewMode('create');
  };

  const handleUpdateItem = (id: string, updates: Partial<InvoiceItem>) => {
    if (!currentInvoice) return;
    const updatedItems = currentInvoice.items.map(item => 
      item.id === id ? { ...item, ...updates } : item
    );
    setCurrentInvoice({ ...currentInvoice, items: updatedItems });
  };

  const handleDeleteItem = (id: string) => {
    if (!currentInvoice) return;
    setCurrentInvoice({
      ...currentInvoice,
      items: currentInvoice.items.filter(item => item.id !== id)
    });
  };

  const addItem = () => {
    if (!currentInvoice) return;
    const newItem: InvoiceItem = {
      id: Math.random().toString(36).substr(2, 9),
      description: '',
      quantity: 1,
      unitPrice: 0,
      total: 0
    };
    setCurrentInvoice({
      ...currentInvoice,
      items: [...currentInvoice.items, newItem]
    });
  };

  const handleSaveInvoice = async () => {
    if (!currentInvoice) return;

    setIsGeneratingNote(true);
    const aiNote = await generatePersonalizedNote(currentInvoice);
    const finalizedInvoice = { ...currentInvoice, aiGreeting: aiNote };

    setInvoices(prev => {
      const exists = prev.find(i => i.id === finalizedInvoice.id);
      if (exists) {
        return prev.map(i => i.id === finalizedInvoice.id ? finalizedInvoice : i);
      }
      return [finalizedInvoice, ...prev];
    });

    setIsGeneratingNote(false);
    setCurrentInvoice(finalizedInvoice);
    setViewMode('view');
  };

  const handleDeleteInvoice = (id: string) => {
    if (window.confirm('Delete this invoice?')) {
      setInvoices(prev => prev.filter(i => i.id !== id));
    }
  };

  const calculateTotal = (inv: Invoice) => {
    const subtotal = inv.items.reduce((sum, item) => sum + (item.quantity * item.unitPrice), 0);
    return subtotal + (subtotal * inv.taxRate) - inv.discount;
  };

  return (
    <div className="min-h-screen pb-20">
      {/* Header */}
      <header className="bg-white border-b border-slate-200 sticky top-0 z-10 no-print">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between items-center h-16">
            <div className="flex items-center gap-3 cursor-pointer" onClick={() => setViewMode('list')}>
              <div className="bg-indigo-600 p-2 rounded-lg">
                <svg className="w-6 h-6 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 21V5a2 2 0 00-2-2H7a2 2 0 00-2 2v16m14 0h2m-2 0h-5m-9 0H3m2 0h5M9 7h1m-1 4h1m4-4h1m-1 4h1m-5 10v-5a1 1 0 011-1h2a1 1 0 011 1v5m-4 0h4" />
                </svg>
              </div>
              <h1 className="text-xl font-bold text-slate-900 tracking-tight">HotelFlow <span className="text-indigo-600 font-light">Invoice</span></h1>
            </div>
            <div className="flex items-center gap-4">
              <button
                onClick={createNewInvoice}
                className="bg-indigo-600 text-white px-5 py-2.5 rounded-xl font-medium hover:bg-indigo-700 transition-colors shadow-sm flex items-center gap-2"
              >
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 4v16m8-8H4" />
                </svg>
                New Invoice
              </button>
            </div>
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 mt-8">
        {viewMode === 'list' && (
          <div className="space-y-6">
            <div className="flex justify-between items-end">
              <div>
                <h2 className="text-2xl font-bold text-slate-800">Invoice History</h2>
                <p className="text-slate-500">Manage and track all guest bills</p>
              </div>
            </div>

            {invoices.length === 0 ? (
              <div className="bg-white border-2 border-dashed border-slate-200 rounded-3xl p-16 text-center">
                <div className="bg-slate-50 w-20 h-20 rounded-full flex items-center justify-center mx-auto mb-6">
                  <svg className="w-10 h-10 text-slate-300" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="1" d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
                  </svg>
                </div>
                <h3 className="text-xl font-semibold text-slate-700 mb-2">No invoices yet</h3>
                <p className="text-slate-400 mb-8 max-w-sm mx-auto">Create your first hotel invoice to start tracking guest payments and stays.</p>
                <button
                  onClick={createNewInvoice}
                  className="inline-flex items-center gap-2 text-indigo-600 font-semibold hover:text-indigo-700"
                >
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 4v16m8-8H4" />
                  </svg>
                  Create Your First Invoice
                </button>
              </div>
            ) : (
              <div className="bg-white shadow-sm border border-slate-200 rounded-2xl overflow-hidden">
                <table className="w-full text-left">
                  <thead className="bg-slate-50 border-b border-slate-200">
                    <tr>
                      <th className="px-6 py-4 text-xs font-bold uppercase text-slate-500 tracking-wider">Number</th>
                      <th className="px-6 py-4 text-xs font-bold uppercase text-slate-500 tracking-wider">Guest</th>
                      <th className="px-6 py-4 text-xs font-bold uppercase text-slate-500 tracking-wider">Stay Dates</th>
                      <th className="px-6 py-4 text-xs font-bold uppercase text-slate-500 tracking-wider">Total</th>
                      <th className="px-6 py-4 text-xs font-bold uppercase text-slate-500 tracking-wider">Status</th>
                      <th className="px-6 py-4 text-xs font-bold uppercase text-slate-500 tracking-wider text-right">Actions</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-100">
                    {invoices.map((inv) => (
                      <tr key={inv.id} className="hover:bg-slate-50/50 transition-colors">
                        <td className="px-6 py-4 font-mono text-sm text-indigo-600 font-bold">{inv.invoiceNumber}</td>
                        <td className="px-6 py-4">
                          <div className="text-sm font-semibold text-slate-800">{inv.guest.name}</div>
                          <div className="text-xs text-slate-400">{inv.guest.email}</div>
                        </td>
                        <td className="px-6 py-4">
                          <div className="text-sm text-slate-600">{inv.stay.checkIn} - {inv.stay.checkOut}</div>
                          <div className="text-xs text-slate-400">{inv.stay.roomType} (RM: {inv.stay.roomNumber})</div>
                        </td>
                        <td className="px-6 py-4 font-bold text-slate-800">${calculateTotal(inv).toLocaleString()}</td>
                        <td className="px-6 py-4">
                          <span className={`px-3 py-1 rounded-full text-xs font-bold uppercase tracking-wide ${
                            inv.status === 'paid' ? 'bg-green-100 text-green-700' : 'bg-amber-100 text-amber-700'
                          }`}>
                            {inv.status}
                          </span>
                        </td>
                        <td className="px-6 py-4 text-right">
                          <div className="flex justify-end gap-3">
                            <button
                              onClick={() => { setCurrentInvoice(inv); setViewMode('view'); }}
                              className="p-2 text-slate-400 hover:text-indigo-600 transition-colors"
                              title="View/Print"
                            >
                              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" />
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z" />
                              </svg>
                            </button>
                            <button
                              onClick={() => { setCurrentInvoice(inv); setViewMode('create'); }}
                              className="p-2 text-slate-400 hover:text-amber-600 transition-colors"
                              title="Edit"
                            >
                              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M11 5H6a2 2 0 00-2 2v11a2 2 0 00-2 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z" />
                              </svg>
                            </button>
                            <button
                              onClick={() => handleDeleteInvoice(inv.id)}
                              className="p-2 text-slate-400 hover:text-red-600 transition-colors"
                              title="Delete"
                            >
                              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
                              </svg>
                            </button>
                          </div>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </div>
        )}

        {viewMode === 'create' && currentInvoice && (
          <div className="bg-white shadow-xl rounded-3xl overflow-hidden border border-slate-200">
            <div className="p-8 border-b border-slate-100 flex justify-between items-center bg-slate-50/50">
              <div>
                <h2 className="text-2xl font-bold text-slate-800">Drafting Invoice</h2>
                <p className="text-indigo-500 font-mono text-sm">{currentInvoice.invoiceNumber}</p>
              </div>
              <div className="flex gap-4">
                <button
                  onClick={() => setViewMode('list')}
                  className="px-6 py-2.5 text-slate-600 font-semibold hover:bg-slate-100 rounded-xl transition-colors"
                >
                  Cancel
                </button>
                <button
                  onClick={handleSaveInvoice}
                  disabled={isGeneratingNote}
                  className="bg-indigo-600 text-white px-8 py-2.5 rounded-xl font-bold hover:bg-indigo-700 transition-all disabled:opacity-50 disabled:cursor-not-allowed flex items-center gap-2 shadow-lg shadow-indigo-200"
                >
                  {isGeneratingNote ? (
                    <>
                      <svg className="animate-spin h-5 w-5 mr-3" viewBox="0 0 24 24">
                        <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                        <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                      </svg>
                      AI Concierge...
                    </>
                  ) : 'Save & Preview'}
                </button>
              </div>
            </div>

            <div className="p-10 grid grid-cols-1 md:grid-cols-2 gap-12">
              {/* Guest Details */}
              <div className="space-y-6">
                <h3 className="text-xs font-bold text-indigo-400 uppercase tracking-widest flex items-center gap-2">
                  <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z" /></svg>
                  Guest Information
                </h3>
                <div className="grid grid-cols-1 gap-4">
                  <input
                    type="text"
                    placeholder="Guest Full Name"
                    className="w-full px-4 py-3 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none bg-slate-50 focus:bg-white transition-all"
                    value={currentInvoice.guest.name}
                    onChange={(e) => setCurrentInvoice({...currentInvoice, guest: {...currentInvoice.guest, name: e.target.value}})}
                  />
                  <input
                    type="email"
                    placeholder="Email Address"
                    className="w-full px-4 py-3 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none bg-slate-50 focus:bg-white transition-all"
                    value={currentInvoice.guest.email}
                    onChange={(e) => setCurrentInvoice({...currentInvoice, guest: {...currentInvoice.guest, email: e.target.value}})}
                  />
                  <input
                    type="tel"
                    placeholder="Phone Number"
                    className="w-full px-4 py-3 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none bg-slate-50 focus:bg-white transition-all"
                    value={currentInvoice.guest.phone}
                    onChange={(e) => setCurrentInvoice({...currentInvoice, guest: {...currentInvoice.guest, phone: e.target.value}})}
                  />
                  <textarea
                    placeholder="Full Address"
                    rows={3}
                    className="w-full px-4 py-3 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none bg-slate-50 focus:bg-white transition-all"
                    value={currentInvoice.guest.address}
                    onChange={(e) => setCurrentInvoice({...currentInvoice, guest: {...currentInvoice.guest, address: e.target.value}})}
                  />
                </div>
              </div>

              {/* Stay Details */}
              <div className="space-y-6">
                <h3 className="text-xs font-bold text-indigo-400 uppercase tracking-widest flex items-center gap-2">
                  <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg>
                  Stay Configuration
                </h3>
                <div className="grid grid-cols-2 gap-4">
                  <div className="col-span-1">
                    <label className="text-xs text-slate-400 mb-1 block">Room Number</label>
                    <input
                      type="text"
                      className="w-full px-4 py-3 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none bg-slate-50 focus:bg-white transition-all"
                      value={currentInvoice.stay.roomNumber}
                      onChange={(e) => setCurrentInvoice({...currentInvoice, stay: {...currentInvoice.stay, roomNumber: e.target.value}})}
                    />
                  </div>
                  <div className="col-span-1">
                    <label className="text-xs text-slate-400 mb-1 block">Room Type</label>
                    <select
                      className="w-full px-4 py-3 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none bg-slate-50 focus:bg-white transition-all"
                      value={currentInvoice.stay.roomType}
                      onChange={(e) => setCurrentInvoice({...currentInvoice, stay: {...currentInvoice.stay, roomType: e.target.value}})}
                    >
                      {ROOM_TYPES.map(type => <option key={type} value={type}>{type}</option>)}
                    </select>
                  </div>
                  <div className="col-span-1">
                    <label className="text-xs text-slate-400 mb-1 block">Check-in</label>
                    <input
                      type="date"
                      className="w-full px-4 py-3 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none bg-slate-50 focus:bg-white transition-all"
                      value={currentInvoice.stay.checkIn}
                      onChange={(e) => setCurrentInvoice({...currentInvoice, stay: {...currentInvoice.stay, checkIn: e.target.value}})}
                    />
                  </div>
                  <div className="col-span-1">
                    <label className="text-xs text-slate-400 mb-1 block">Check-out</label>
                    <input
                      type="date"
                      className="w-full px-4 py-3 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none bg-slate-50 focus:bg-white transition-all"
                      value={currentInvoice.stay.checkOut}
                      onChange={(e) => setCurrentInvoice({...currentInvoice, stay: {...currentInvoice.stay, checkOut: e.target.value}})}
                    />
                  </div>
                </div>
                <div>
                  <label className="text-xs text-slate-400 mb-1 block">Status</label>
                  <div className="flex gap-4">
                    {['draft', 'paid', 'cancelled'].map(status => (
                      <button
                        key={status}
                        onClick={() => setCurrentInvoice({...currentInvoice, status: status as any})}
                        className={`flex-1 py-2 px-4 rounded-xl text-xs font-bold uppercase transition-all ${
                          currentInvoice.status === status 
                          ? 'bg-indigo-600 text-white shadow-md' 
                          : 'bg-slate-100 text-slate-500 hover:bg-slate-200'
                        }`}
                      >
                        {status}
                      </button>
                    ))}
                  </div>
                </div>
              </div>

              {/* Items Table */}
              <div className="col-span-full space-y-4">
                <div className="flex justify-between items-center">
                  <h3 className="text-xs font-bold text-indigo-400 uppercase tracking-widest">Billing Line Items</h3>
                  <button
                    onClick={addItem}
                    className="text-sm font-bold text-indigo-600 hover:text-indigo-800 flex items-center gap-1"
                  >
                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 4v16m8-8H4" /></svg>
                    Add Service
                  </button>
                </div>
                <div className="bg-slate-50 p-6 rounded-2xl border border-slate-200">
                  <div className="grid grid-cols-12 gap-4 mb-4 text-xs font-bold uppercase text-slate-400 px-3">
                    <div className="col-span-6">Description</div>
                    <div className="col-span-2 text-center">Qty</div>
                    <div className="col-span-2 text-right">Unit Price</div>
                    <div className="col-span-1 text-right">Amount</div>
                    <div className="col-span-1"></div>
                  </div>
                  {currentInvoice.items.map(item => (
                    <InvoiceItemRow
                      key={item.id}
                      item={item}
                      onUpdate={handleUpdateItem}
                      onDelete={handleDeleteItem}
                    />
                  ))}
                  {currentInvoice.items.length === 0 && (
                    <div className="text-center py-8 text-slate-400">No items added yet.</div>
                  )}
                </div>
              </div>

              {/* Totals & Adjustments */}
              <div className="col-span-full md:col-start-2">
                <div className="bg-slate-50 p-6 rounded-2xl space-y-4 border border-slate-200">
                  <div className="flex justify-between items-center">
                    <span className="text-slate-500 font-medium">Tax Rate</span>
                    <div className="flex items-center gap-2">
                      <input
                        type="number"
                        className="w-16 px-2 py-1 text-right border rounded-lg focus:ring-1 focus:ring-indigo-500"
                        value={currentInvoice.taxRate * 100}
                        onChange={(e) => setCurrentInvoice({...currentInvoice, taxRate: Number(e.target.value) / 100})}
                      />
                      <span className="text-slate-400">%</span>
                    </div>
                  </div>
                  <div className="flex justify-between items-center">
                    <span className="text-slate-500 font-medium">Discount (USD)</span>
                    <input
                      type="number"
                      className="w-32 px-2 py-1 text-right border rounded-lg focus:ring-1 focus:ring-indigo-500"
                      value={currentInvoice.discount}
                      onChange={(e) => setCurrentInvoice({...currentInvoice, discount: Number(e.target.value)})}
                    />
                  </div>
                  <div className="border-t pt-4 flex justify-between items-end">
                    <span className="text-slate-800 font-bold text-lg uppercase tracking-wider">Grand Total</span>
                    <span className="text-3xl font-serif font-bold text-indigo-600">${calculateTotal(currentInvoice).toLocaleString()}</span>
                  </div>
                </div>
              </div>
            </div>
          </div>
        )}

        {viewMode === 'view' && currentInvoice && (
          <div className="space-y-8 animate-in fade-in duration-500">
            <div className="flex justify-between items-center no-print">
              <button
                onClick={() => setViewMode('list')}
                className="flex items-center gap-2 text-slate-500 font-semibold hover:text-slate-800 transition-colors"
              >
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M10 19l-7-7m0 0l7-7m-7 7h18" />
                </svg>
                Back to History
              </button>
              <div className="flex gap-4">
                <button
                  onClick={() => window.print()}
                  className="bg-slate-800 text-white px-6 py-2.5 rounded-xl font-bold hover:bg-slate-900 transition-all flex items-center gap-2"
                >
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4a2 2 0 00-2-2H9a2 2 0 00-2 2v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z" />
                  </svg>
                  Print Invoice
                </button>
                <button
                  onClick={() => setViewMode('create')}
                  className="bg-indigo-600 text-white px-6 py-2.5 rounded-xl font-bold hover:bg-indigo-700 transition-all flex items-center gap-2"
                >
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z" />
                  </svg>
                  Edit Invoice
                </button>
              </div>
            </div>

            <InvoicePreview invoice={currentInvoice} />
          </div>
        )}
      </main>

      {/* Footer Mobile/Sticky FAB */}
      <footer className="fixed bottom-0 left-0 right-0 bg-white/80 backdrop-blur-md border-t border-slate-200 p-4 md:hidden no-print">
        <button
          onClick={createNewInvoice}
          className="w-full bg-indigo-600 text-white py-4 rounded-2xl font-bold text-lg shadow-xl shadow-indigo-200 active:scale-95 transition-all"
        >
          Create New Invoice
        </button>
      </footer>
    </div>
  );
};

export default App;

