import React, { useState, useEffect } from 'react';
import { Invoice, ViewMode, InvoiceItem, Payment, HotelSettings } from './types';
import { InvoicePreview } from './components/InvoicePreview';
import { InvoiceItemRow } from './components/InvoiceItemRow';
import { PaymentRow } from './components/PaymentRow';
import { SettingsPage } from './components/SettingsPage';
import { ROOM_TYPES, PAYMENT_METHODS, HOTEL_INFO, TAX_RATE } from './constants';
import { generatePersonalizedNote } from './services/geminiService';

const INITIAL_GUEST = { name: '', email: '', phone: '', address: '' };
const INITIAL_STAY = { roomNumber: '', roomType: ROOM_TYPES[0], checkIn: '', checkOut: '', guestsCount: 1 };

const App: React.FC = () => {
  const [viewMode, setViewMode] = useState<ViewMode>('list');
  const [invoices, setInvoices] = useState<Invoice[]>([]);
  const [currentInvoice, setCurrentInvoice] = useState<Invoice | null>(null);
  const [isGeneratingNote, setIsGeneratingNote] = useState(false);
  const [settings, setSettings] = useState<HotelSettings>({
    ...HOTEL_INFO,
    defaultTaxRate: TAX_RATE
  });

  // Load from local storage
  useEffect(() => {
    const savedInvoices = localStorage.getItem('hotelflow_invoices');
    if (savedInvoices) setInvoices(JSON.parse(savedInvoices));

    const savedSettings = localStorage.getItem('hotelflow_settings');
    if (savedSettings) setSettings(JSON.parse(savedSettings));
  }, []);

  // Save to local storage
  useEffect(() => {
    localStorage.setItem('hotelflow_invoices', JSON.stringify(invoices));
  }, [invoices]);

  const handleSaveSettings = (newSettings: HotelSettings) => {
    setSettings(newSettings);
    localStorage.setItem('hotelflow_settings', JSON.stringify(newSettings));
  };

  const createNewInvoice = () => {
    const id = Math.random().toString(36).substr(2, 9);
    const newInvoice: Invoice = {
      id,
      invoiceNumber: `INV-${new Date().getFullYear()}-${Math.floor(Math.random() * 9000 + 1000)}`,
      date: new Date().toISOString().split('T')[0],
      guest: { ...INITIAL_GUEST },
      stay: { ...INITIAL_STAY },
      items: [
        { id: '1', description: '', quantity: 1, nights: 1, unitPrice: 0, total: 0 }
      ],
      payments: [],
      taxRate: settings.defaultTaxRate,
      discount: 0,
      status: 'draft',
      notes: '',
      hotelSnap: settings
    };
    setCurrentInvoice(newInvoice);
    setViewMode('create');
  };

  const handleUpdateItem = (id: string, updates: Partial<InvoiceItem>) => {
    if (!currentInvoice) return;
    const updatedItems = currentInvoice.items.map(item => 
      item.id === id ? { ...item, ...updates } : item
    );
    setCurrentInvoice({ ...currentInvoice, items: updatedItems });
  };

  const handleDeleteItem = (id: string) => {
    if (!currentInvoice) return;
    setCurrentInvoice({
      ...currentInvoice,
      items: currentInvoice.items.filter(item => item.id !== id)
    });
  };

  const addItem = () => {
    if (!currentInvoice) return;
    const newItem: InvoiceItem = {
      id: Math.random().toString(36).substr(2, 9),
      description: '',
      quantity: 1,
      nights: 1,
      unitPrice: 0,
      total: 0
    };
    setCurrentInvoice({
      ...currentInvoice,
      items: [...currentInvoice.items, newItem]
    });
  };

  const handleUpdatePayment = (id: string, updates: Partial<Payment>) => {
    if (!currentInvoice) return;
    const updatedPayments = currentInvoice.payments.map(p => 
      p.id === id ? { ...p, ...updates } : p
    );
    setCurrentInvoice({ ...currentInvoice, payments: updatedPayments });
  };

  const handleDeletePayment = (id: string) => {
    if (!currentInvoice) return;
    setCurrentInvoice({
      ...currentInvoice,
      payments: currentInvoice.payments.filter(p => p.id !== id)
    });
  };

  const addPayment = () => {
    if (!currentInvoice) return;
    const newPayment: Payment = {
      id: Math.random().toString(36).substr(2, 9),
      date: new Date().toISOString().split('T')[0],
      method: PAYMENT_METHODS[0],
      amount: 0
    };
    setCurrentInvoice({
      ...currentInvoice,
      payments: [...currentInvoice.payments, newPayment]
    });
  };

  const handleSaveInvoice = async () => {
    if (!currentInvoice) return;

    setIsGeneratingNote(true);
    const aiNote = await generatePersonalizedNote(currentInvoice);
    const finalizedInvoice = { ...currentInvoice, aiGreeting: aiNote, hotelSnap: settings };

    setInvoices(prev => {
      const exists = prev.find(i => i.id === finalizedInvoice.id);
      if (exists) {
        return prev.map(i => i.id === finalizedInvoice.id ? finalizedInvoice : i);
      }
      return [finalizedInvoice, ...prev];
    });

    setIsGeneratingNote(false);
    setCurrentInvoice(finalizedInvoice);
    setViewMode('view');
  };

  const handleDeleteInvoice = (id: string) => {
    if (window.confirm('Hapus invoice ini?')) {
      setInvoices(prev => prev.filter(i => i.id !== id));
    }
  };

  const calculateTotal = (inv: Invoice) => {
    const subtotal = inv.items.reduce((sum, item) => sum + (item.quantity * item.nights * item.unitPrice), 0);
    return subtotal + (subtotal * inv.taxRate) - inv.discount;
  };

  const calculatePaid = (inv: Invoice) => {
    return inv.payments.reduce((sum, p) => sum + p.amount, 0);
  };

  const formatCurrency = (val: number) => {
    return val.toLocaleString('id-ID');
  };

  return (
    <div className="min-h-screen bg-slate-50">
      {/* Header & Nav */}
      <header className="bg-white border-b border-slate-200 sticky top-0 z-10 no-print">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between items-center h-16">
            <div className="flex items-center gap-8">
              <div className="flex items-center gap-3 cursor-pointer" onClick={() => setViewMode('list')}>
                <div className="bg-indigo-600 p-2 rounded-lg">
                  <svg className="w-6 h-6 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 21V5a2 2 0 00-2-2H7a2 2 0 00-2 2v16m14 0h2m-2 0h-5m-9 0H3m2 0h5M9 7h1m-1 4h1m4-4h1m-1 4h1m-5 10v-5a1 1 0 011-1h2a1 1 0 011 1v5m-4 0h4" />
                  </svg>
                </div>
                <h1 className="text-xl font-bold text-slate-900 tracking-tight hidden sm:block">HotelFlow <span className="text-indigo-600 font-light">Pro</span></h1>
              </div>

              <nav className="flex items-center gap-1">
                <button
                  onClick={() => setViewMode('list')}
                  className={`px-4 py-2 rounded-lg text-sm font-semibold transition-all ${
                    viewMode === 'list' ? 'bg-indigo-50 text-indigo-600' : 'text-slate-500 hover:text-slate-800'
                  }`}
                >
                  Daftar Invoice
                </button>
                <button
                  onClick={() => setViewMode('settings')}
                  className={`px-4 py-2 rounded-lg text-sm font-semibold transition-all ${
                    viewMode === 'settings' ? 'bg-indigo-50 text-indigo-600' : 'text-slate-500 hover:text-slate-800'
                  }`}
                >
                  Pengaturan
                </button>
              </nav>
            </div>

            <div className="flex items-center gap-4">
              <button
                onClick={createNewInvoice}
                className="bg-indigo-600 text-white px-5 py-2.5 rounded-xl font-medium hover:bg-indigo-700 transition-colors shadow-sm flex items-center gap-2"
              >
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 4v16m8-8H4" />
                </svg>
                <span className="hidden sm:inline">Buat Invoice</span>
                <span className="sm:hidden">+</span>
              </button>
            </div>
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        {viewMode === 'settings' && (
          <SettingsPage settings={settings} onSave={handleSaveSettings} />
        )}

        {viewMode === 'list' && (
          <div className="space-y-6 animate-in fade-in slide-in-from-top-4 duration-500">
            <div className="flex justify-between items-end">
              <div>
                <h2 className="text-2xl font-bold text-slate-800">Riwayat Tagihan</h2>
                <p className="text-slate-500">Kumpulan semua invoice tamu yang telah dibuat.</p>
              </div>
            </div>

            {invoices.length === 0 ? (
              <div className="bg-white border-2 border-dashed border-slate-200 rounded-3xl p-16 text-center">
                <div className="bg-slate-50 w-20 h-20 rounded-full flex items-center justify-center mx-auto mb-6">
                  <svg className="w-10 h-10 text-slate-300" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="1" d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
                  </svg>
                </div>
                <h3 className="text-xl font-semibold text-slate-700 mb-2">Daftar Invoice Kosong</h3>
                <p className="text-slate-400 mb-8 max-w-sm mx-auto">Mulai dengan membuat invoice baru untuk tamu Anda.</p>
                <button
                  onClick={createNewInvoice}
                  className="inline-flex items-center gap-2 text-indigo-600 font-semibold hover:text-indigo-700"
                >
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 4v16m8-8H4" />
                  </svg>
                  Buat Sekarang
                </button>
              </div>
            ) : (
              <div className="bg-white shadow-sm border border-slate-200 rounded-2xl overflow-hidden overflow-x-auto">
                <table className="w-full text-left min-w-[800px]">
                  <thead className="bg-slate-50 border-b border-slate-200">
                    <tr>
                      <th className="px-6 py-4 text-xs font-bold uppercase text-slate-500 tracking-wider">Nomor</th>
                      <th className="px-6 py-4 text-xs font-bold uppercase text-slate-500 tracking-wider">Tamu</th>
                      <th className="px-6 py-4 text-xs font-bold uppercase text-slate-500 tracking-wider">Tanggal Menginap</th>
                      <th className="px-6 py-4 text-xs font-bold uppercase text-slate-500 tracking-wider">Total</th>
                      <th className="px-6 py-4 text-xs font-bold uppercase text-slate-500 tracking-wider">Status</th>
                      <th className="px-6 py-4 text-xs font-bold uppercase text-slate-500 tracking-wider text-right">Aksi</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-100">
                    {invoices.map((inv) => (
                      <tr key={inv.id} className="hover:bg-slate-50/50 transition-colors group">
                        <td className="px-6 py-4 font-mono text-sm text-indigo-600 font-bold">{inv.invoiceNumber}</td>
                        <td className="px-6 py-4">
                          <div className="text-sm font-semibold text-slate-800">{inv.guest.name}</div>
                          <div className="text-xs text-slate-400">{inv.guest.email}</div>
                        </td>
                        <td className="px-6 py-4">
                          <div className="text-sm text-slate-600">{inv.stay.checkIn} - {inv.stay.checkOut}</div>
                          <div className="text-xs text-slate-400">{inv.stay.roomType} (RM: {inv.stay.roomNumber})</div>
                        </td>
                        <td className="px-6 py-4 font-bold text-slate-800">Rp {formatCurrency(calculateTotal(inv))}</td>
                        <td className="px-6 py-4">
                          <span className={`px-3 py-1 rounded-full text-[10px] font-bold uppercase tracking-wide ${
                            inv.status === 'paid' ? 'bg-green-100 text-green-700' : 
                            inv.status === 'cancelled' ? 'bg-red-100 text-red-700' : 'bg-amber-100 text-amber-700'
                          }`}>
                            {inv.status}
                          </span>
                        </td>
                        <td className="px-6 py-4 text-right">
                          <div className="flex justify-end gap-1">
                            <button
                              onClick={() => { setCurrentInvoice(inv); setViewMode('view'); }}
                              className="p-2 text-slate-400 hover:text-indigo-600 transition-colors rounded-lg hover:bg-indigo-50"
                              title="Lihat"
                            >
                              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" />
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z" />
                              </svg>
                            </button>
                            <button
                              onClick={() => { setCurrentInvoice(inv); setViewMode('create'); }}
                              className="p-2 text-slate-400 hover:text-amber-600 transition-colors rounded-lg hover:bg-amber-50"
                              title="Edit"
                            >
                              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M11 5H6a2 2 0 00-2 2v11a2 2 0 00-2 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z" />
                              </svg>
                            </button>
                            <button
                              onClick={() => handleDeleteInvoice(inv.id)}
                              className="p-2 text-slate-400 hover:text-red-600 transition-colors rounded-lg hover:bg-red-50"
                              title="Hapus"
                            >
                              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
                              </svg>
                            </button>
                          </div>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </div>
        )}

        {viewMode === 'create' && currentInvoice && (
          <div className="bg-white shadow-xl rounded-3xl overflow-hidden border border-slate-200">
            {/* ... sama seperti sebelumnya ... */}
            <div className="p-8 border-b border-slate-100 flex justify-between items-center bg-slate-50/50">
              <div>
                <h2 className="text-2xl font-bold text-slate-800">Draft Invoice</h2>
                <p className="text-indigo-500 font-mono text-sm">{currentInvoice.invoiceNumber}</p>
              </div>
              <div className="flex gap-4">
                <button
                  onClick={() => setViewMode('list')}
                  className="px-6 py-2.5 text-slate-600 font-semibold hover:bg-slate-100 rounded-xl transition-colors"
                >
                  Batal
                </button>
                <button
                  onClick={handleSaveInvoice}
                  disabled={isGeneratingNote}
                  className="bg-indigo-600 text-white px-8 py-2.5 rounded-xl font-bold hover:bg-indigo-700 transition-all disabled:opacity-50 disabled:cursor-not-allowed flex items-center gap-2 shadow-lg shadow-indigo-200"
                >
                  {isGeneratingNote ? (
                    <>
                      <svg className="animate-spin h-5 w-5 mr-3" viewBox="0 0 24 24">
                        <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                        <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                      </svg>
                      AI Concierge...
                    </>
                  ) : 'Simpan & Lihat'}
