                          ? 'bg-indigo-600 text-white shadow-md' 
                          : 'bg-slate-100 text-slate-500 hover:bg-slate-200'
                        }`}
                      >
                        {status}
                      </button>
                    ))}
                  </div>
                </div>
              </div>

              <div className="col-span-full space-y-4">
                <div className="flex justify-between items-center">
                  <h3 className="text-xs font-bold text-indigo-400 uppercase tracking-widest">Rincian Layanan</h3>
                  <button
                    onClick={addItem}
                    className="text-sm font-bold text-indigo-600 hover:text-indigo-800 flex items-center gap-1 transition-colors"
                  >
                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 4v16m8-8H4" /></svg>
                    Tambah Layanan
                  </button>
                </div>
                <div className="bg-slate-50 p-6 rounded-2xl border border-slate-200">
                  {currentInvoice.items.map(item => (
                    <InvoiceItemRow
                      key={item.id}
                      item={item}
                      onUpdate={handleUpdateItem}
                      onDelete={handleDeleteItem}
                    />
                  ))}
                </div>
              </div>

              <div className="col-span-full space-y-4">
                <div className="flex justify-between items-center">
                  <h3 className="text-xs font-bold text-emerald-500 uppercase tracking-widest">Pembayaran Diterima</h3>
                  <button
                    onClick={addPayment}
                    className="text-sm font-bold text-emerald-600 hover:text-emerald-800 flex items-center gap-1 transition-colors"
                  >
                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 4v16m8-8H4" /></svg>
                    Tambah Pembayaran
                  </button>
                </div>
                <div className="bg-emerald-50/50 p-6 rounded-2xl border border-emerald-100">
                  {currentInvoice.payments.map(p => (
                    <PaymentRow
                      key={p.id}
                      payment={p}
                      onUpdate={handleUpdatePayment}
                      onDelete={handleDeletePayment}
                    />
                  ))}
                </div>
              </div>

              <div className="col-span-full md:col-start-2">
                <div className="bg-slate-50 p-6 rounded-2xl space-y-4 border border-slate-200">
                  <div className="flex justify-between items-center text-sm">
                    <span className="text-slate-500 font-medium">Subtotal</span>
                    <span className="text-slate-800 font-bold">Rp {formatCurrency(currentInvoice.items.reduce((sum, item) => sum + (item.quantity * item.nights * item.unitPrice), 0))}</span>
                  </div>
                  <div className="flex justify-between items-center">
                    <span className="text-slate-500 font-medium">Tarif Pajak</span>
                    <div className="flex items-center gap-2">
                      <input
                        type="number"
                        className="w-16 px-2 py-1 text-right border rounded-lg focus:ring-1 focus:ring-indigo-500"
                        value={currentInvoice.taxRate * 100}
                        onChange={(e) => setCurrentInvoice({...currentInvoice, taxRate: Number(e.target.value) / 100})}
                      />
                      <span className="text-slate-400">%</span>
                    </div>
                  </div>
                  <div className="flex justify-between items-center">
                    <span className="text-slate-500 font-medium">Diskon (IDR)</span>
                    <input
                      type="number"
                      className="w-32 px-2 py-1 text-right border rounded-lg focus:ring-1 focus:ring-indigo-500"
                      value={currentInvoice.discount}
                      onChange={(e) => setCurrentInvoice({...currentInvoice, discount: Number(e.target.value)})}
                    />
                  </div>
                  <div className="border-t border-slate-200 pt-4 flex justify-between items-end">
                    <span className="text-slate-800 font-bold text-lg uppercase tracking-wider">Total Tagihan</span>
                    <span className="text-2xl font-serif font-bold text-slate-800">Rp {formatCurrency(calculateTotal(currentInvoice))}</span>
                  </div>
                  <div className="flex justify-between items-center text-emerald-600 font-medium pt-2">
                    <span>Total Dibayar</span>
                    <span>- Rp {formatCurrency(calculatePaid(currentInvoice))}</span>
                  </div>
                  <div className="border-t border-indigo-200 pt-4 flex justify-between items-end">
                    <span className="text-indigo-800 font-bold text-lg uppercase tracking-wider">Sisa Tagihan</span>
                    <span className="text-3xl font-serif font-bold text-indigo-600">
                      Rp {formatCurrency(calculateTotal(currentInvoice) - calculatePaid(currentInvoice))}
                    </span>
                  </div>
                </div>
              </div>
            </div>
          </div>
        )}

        {viewMode === 'view' && currentInvoice && (
          <div className="space-y-8 animate-in fade-in duration-500">
             <div className="flex justify-between items-center no-print">
              <button
                onClick={() => setViewMode('list')}
                className="flex items-center gap-2 text-slate-500 font-semibold hover:text-slate-800 transition-colors"
              >
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M10 19l-7-7m0 0l7-7m-7 7h18" />
                </svg>
                Kembali ke Riwayat
              </button>
              <div className="flex gap-4">
                <button
                  onClick={() => window.print()}
                  className="bg-slate-800 text-white px-6 py-2.5 rounded-xl font-bold hover:bg-slate-900 transition-all flex items-center gap-2"
                >
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4a2 2 0 00-2-2H9a2 2 0 00-2 2v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z" />
                  </svg>
                  Cetak Invoice
                </button>
              </div>
            </div>
            <InvoicePreview invoice={currentInvoice} settings={settings} />
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

payload.text:
### Instruksi Tambahan untuk Google Apps Script:

Agar sinkronisasi bekerja, Anda perlu membuat Google Apps Script dengan kode berikut:

1. Buka Google Sheet.
2. Klik **Extensions > Apps Script**.
3. Masukkan kode ini:

```javascript
function doPost(e) {
  var ss = SpreadsheetApp.getActiveSpreadsheet();
  var sheet = ss.getSheetByName("Invoices") || ss.insertSheet("Invoices");

  // Ambil data JSON dari body request
  var data = JSON.parse(e.postData.contents);

  // Setel Header jika sheet baru
  if (sheet.getLastRow() == 0) {
    sheet.appendRow(["Invoice No", "Date", "Guest Name", "Room", "Total", "Paid", "Balance", "Status"]);
    sheet.getRange(1, 1, 1, 8).setFontWeight("bold").setBackground("#f3f3f3");
  }

  // Hapus data lama (opsional, tergantung apakah ingin sync ulang atau append)
  // Untuk sinkronisasi database penuh, kita hapus lalu tulis ulang:
  if (sheet.getLastRow() > 1) {
    sheet.getRange(2, 1, sheet.getLastRow() - 1, 8).clearContent();
  }

  // Tulis data baru
  data.forEach(function(inv) {
    sheet.appendRow([
      inv.invoiceNumber,
      inv.date,
      inv.guestName,
      inv.roomNumber,
      inv.totalAmount,
      inv.paidAmount,
      inv.balanceDue,
      inv.status
    ]);
  });

  return ContentService.createTextOutput(JSON.stringify({status: "success"}))
    .setMimeType(ContentService.MimeType.JSON);
}
```

4. Klik **Deploy > New Deployment**.
5. Pilih tipe **Web App**.
6. Atur "Execute as" ke **Me** dan "Who has access" ke **Anyone**.
7. Salin URL yang diberikan dan tempelkan ke menu **Pengaturan** di aplikasi HotelFlow Anda.

