                    <span>- Rp {formatCurrency(calculatePaid(currentInvoice))}</span>
                  </div>
                  <div className="border-t border-indigo-200 pt-4 flex justify-between items-end">
                    <span className="text-indigo-800 font-bold text-lg uppercase tracking-wider">Sisa Tagihan</span>
                    <span className="text-3xl font-serif font-bold text-indigo-600">
                      Rp {formatCurrency(calculateTotal(currentInvoice) - calculatePaid(currentInvoice))}
                    </span>
                  </div>
                </div>
              </div>
            </div>
          </div>
        )}

        {viewMode === 'view' && currentInvoice && (
          <div className="space-y-8 animate-in fade-in duration-500">
