### Instruksi Google Apps Script Baru:

Gunakan kode di bawah ini pada Google Spreadsheet Anda agar bisa menangani penyimpanan **Pengaturan** dan **Invoice** secara bersamaan:

```javascript
function doPost(e) {
  var data = JSON.parse(e.postData.contents);
  var ss = SpreadsheetApp.getActiveSpreadsheet();

  // Jika tipe data adalah PENGATURAN
  if (data.type === 'settings') {
    var sheet = ss.getSheetByName("Settings") || ss.insertSheet("Settings");
    sheet.clear(); // Bersihkan pengaturan lama
    sheet.appendRow(["Field", "Value"]);
    Object.keys(data.payload).forEach(function(key) {
      sheet.appendRow([key, data.payload[key]]);
    });
  } 

  // Jika tipe data adalah INVOICE
  else if (data.type === 'invoice') {
    var sheet = ss.getSheetByName("Invoices") || ss.insertSheet("Invoices");
    if (sheet.getLastRow() == 0) {
      sheet.appendRow(["Invoice No", "Date", "Guest Name", "Room", "Total", "Paid", "Balance", "Status", "Timestamp"]);
      sheet.getRange(1, 1, 1, 9).setFontWeight("bold").setBackground("#f3f3f3");
    }

    var inv = data.payload;
    sheet.appendRow([
      inv.invoiceNumber,
      inv.date,
      inv.guestName,
      inv.roomNumber,
      inv.totalAmount,
      inv.paidAmount,
      inv.balanceDue,
      inv.status,
      new Date()
    ]);
  }

  return ContentService.createTextOutput(JSON.stringify({status: "success"}))
    .setMimeType(ContentService.MimeType.JSON);
}
```

Dengan skrip ini, Anda cukup memasukkan satu URL Web App di halaman Pengaturan, dan aplikasi akan secara cerdas memilah apakah harus menyimpan profil hotel atau riwayat transaksi tamu ke tab yang berbeda. Semua proses ini berjalan otomatis di latar belakang tanpa mengganggu alur kerja Anda.

