      date: finalizedInvoice.date,
      guestName: finalizedInvoice.guest.name,
      roomNumber: finalizedInvoice.stay.roomNumber,
      totalAmount: calculateTotal(finalizedInvoice),
      paidAmount: calculatePaid(finalizedInvoice),
      balanceDue: calculateTotal(finalizedInvoice) - calculatePaid(finalizedInvoice),
      status: finalizedInvoice.status
    });
  };

  const createNewInvoice = () => {
