        syncStatus === 'success' ? 'bg-emerald-500 text-white translate-y-0' :
        syncStatus === 'error' ? 'bg-red-500 text-white translate-y-0' : 'translate-y-20 opacity-0'
      }`}>
        <div className="flex items-center gap-2">
          {syncStatus === 'syncing' && <svg className="animate-spin h-3 w-3 text-white" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg>}
          {syncStatus === 'syncing' ? 'Syncing...' : syncStatus === 'success' ? 'Cloud Updated' : 'Sync Error'}
        </div>
