                            <button onClick={() => { setCurrentInvoice(inv); setViewMode('view'); }} className="p-2 text-slate-400 hover:text-indigo-600"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z" /></svg></button>
                            <button onClick={() => { setCurrentInvoice(inv); setViewMode('create'); }} className="p-2 text-slate-400 hover:text-amber-600"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M11 5H6a2 2 0 00-2 2v11a2 2 0 00-2 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z" /></svg></button>
                          </div>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </div>
        )}

        {viewMode === 'create' && currentInvoice && (
          <div className="bg-white shadow-xl rounded-3xl overflow-hidden border border-slate-200 animate-in zoom-in-95 duration-300">
             <div className="p-8 border-b border-slate-100 flex justify-between items-center bg-slate-50/50">
              <div className="flex items-center gap-4">
                <button 
                  onClick={handleMinimize}
                  className="p-2 text-slate-400 hover:text-indigo-600 hover:bg-white rounded-lg transition-all"
                  title="Minimize Draft"
                >
                  <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M18 12H6" /></svg>
                </button>
                <div>
                  <h2 className="text-2xl font-bold text-slate-800">Draft Invoice</h2>
                  <p className="text-indigo-500 font-mono text-sm">{currentInvoice.invoiceNumber}</p>
                </div>
              </div>
              <div className="flex gap-4">
                <button onClick={() => setViewMode('list')} className="px-6 py-2.5 text-slate-600 font-semibold hover:bg-slate-100 rounded-xl transition-colors">Batal</button>
                <button onClick={handleSaveInvoice} disabled={isGeneratingNote} className="bg-indigo-600 text-white px-8 py-2.5 rounded-xl font-bold hover:bg-indigo-700 transition-all disabled:opacity-50 flex items-center gap-2 shadow-lg shadow-indigo-200">
                  {isGeneratingNote ? 'AI Menyiapkan...' : 'Simpan (Auto-Sync)'}
                </button>
              </div>
            </div>

            <div className="p-10 grid grid-cols-1 md:grid-cols-2 gap-12">
              <div className="space-y-6">
                <h3 className="text-xs font-bold text-indigo-400 uppercase tracking-widest flex items-center gap-2">
                  <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z" /></svg>
                  Informasi Tamu
                </h3>
                <div className="grid grid-cols-1 gap-4">
                  <input type="text" placeholder="Nama Lengkap Tamu" className="w-full px-4 py-3 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none bg-slate-50 focus:bg-white transition-all uppercase" value={currentInvoice.guest.name} onChange={(e) => setCurrentInvoice({...currentInvoice, guest: {...currentInvoice.guest, name: e.target.value.toUpperCase()}})} />
                  <input type="email" placeholder="Alamat Email" className="w-full px-4 py-3 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none bg-slate-50 focus:bg-white transition-all" value={currentInvoice.guest.email} onChange={(e) => setCurrentInvoice({...currentInvoice, guest: {...currentInvoice.guest, email: e.target.value}})} />
                  <textarea placeholder="Alamat Lengkap" rows={3} className="w-full px-4 py-3 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none bg-slate-50 focus:bg-white transition-all" value={currentInvoice.guest.address} onChange={(e) => setCurrentInvoice({...currentInvoice, guest: {...currentInvoice.guest, address: e.target.value}})} />
                </div>
              </div>

              <div className="space-y-6">
                <h3 className="text-xs font-bold text-indigo-400 uppercase tracking-widest flex items-center gap-2">
                  <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg>
                  Konfigurasi Menginap
                </h3>
                <div className="grid grid-cols-2 gap-4">
                  <div className="col-span-1"><label className="text-xs text-slate-400 mb-1 block">Nomor Kamar</label><input type="text" className="w-full px-4 py-3 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none bg-slate-50" value={currentInvoice.stay.roomNumber} onChange={(e) => setCurrentInvoice({...currentInvoice, stay: {...currentInvoice.stay, roomNumber: e.target.value}})} /></div>
                  <div className="col-span-1"><label className="text-xs text-slate-400 mb-1 block">Tipe Kamar</label><select className="w-full px-4 py-3 border border-slate-200 rounded-xl" value={currentInvoice.stay.roomType} onChange={(e) => setCurrentInvoice({...currentInvoice, stay: {...currentInvoice.stay, roomType: e.target.value}})}>{ROOM_TYPES.map(type => <option key={type} value={type}>{type}</option>)}</select></div>
                  <div className="col-span-1"><label className="text-xs text-slate-400 mb-1 block">Check-in</label><input type="date" className="w-full px-4 py-3 border border-slate-200 rounded-xl" value={currentInvoice.stay.checkIn} onChange={(e) => setCurrentInvoice({...currentInvoice, stay: {...currentInvoice.stay, checkIn: e.target.value}})} /></div>
                  <div className="col-span-1"><label className="text-xs text-slate-400 mb-1 block">Check-out</label><input type="date" className="w-full px-4 py-3 border border-slate-200 rounded-xl" value={currentInvoice.stay.checkOut} onChange={(e) => setCurrentInvoice({...currentInvoice, stay: {...currentInvoice.stay, checkOut: e.target.value}})} /></div>
                </div>
                <div>
                  <label className="text-xs text-slate-400 mb-1 block">Status</label>
                  <div className="flex gap-4">
                    {['draft', 'paid', 'cancelled'].map(status => (
                      <button key={status} onClick={() => setCurrentInvoice({...currentInvoice, status: status as any})} className={`flex-1 py-2 px-4 rounded-xl text-xs font-bold uppercase transition-all ${currentInvoice.status === status ? 'bg-indigo-600 text-white shadow-md' : 'bg-slate-100 text-slate-500 hover:bg-slate-200'}`}>{status}</button>
                    ))}
                  </div>
                </div>
              </div>

              <div className="col-span-full space-y-4">
                <div className="flex justify-between items-center"><h3 className="text-xs font-bold text-indigo-400 uppercase tracking-widest">Rincian Layanan</h3><button onClick={addItem} className="text-sm font-bold text-indigo-600 hover:text-indigo-800 flex items-center gap-1 transition-colors"><svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 4v16m8-8H4" /></svg>Tambah Layanan</button></div>
                <div className="bg-slate-50 p-6 rounded-2xl border border-slate-200">
                  {currentInvoice.items.map(item => (<InvoiceItemRow key={item.id} item={item} onUpdate={handleUpdateItem} onDelete={handleDeleteItem} />))}
                </div>
              </div>

              <div className="col-span-full space-y-4">
                <div className="flex justify-between items-center"><h3 className="text-xs font-bold text-emerald-500 uppercase tracking-widest">Pembayaran Diterima</h3><button onClick={addPayment} className="text-sm font-bold text-emerald-600 hover:text-emerald-800 flex items-center gap-1 transition-colors"><svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 4v16m8-8H4" /></svg>Tambah Pembayaran</button></div>
                <div className="bg-emerald-50/50 p-6 rounded-2xl border border-emerald-100">
                  {currentInvoice.payments.map(p => (<PaymentRow key={p.id} payment={p} onUpdate={handleUpdatePayment} onDelete={() => {}} />))}
                </div>
              </div>

              <div className="col-span-full md:col-start-2">
                <div className="bg-slate-50 p-6 rounded-2xl space-y-4 border border-slate-200">
                  <div className="flex justify-between items-center text-sm"><span className="text-slate-500 font-medium">Subtotal</span><span className="text-slate-800 font-bold">Rp {formatCurrency(currentInvoice.items.reduce((sum, item) => sum + (item.quantity * item.nights * item.unitPrice), 0))}</span></div>
                  <div className="flex justify-between items-center"><span className="text-slate-500 font-medium">Diskon (IDR)</span><input type="text" className="w-32 px-2 py-1 text-right border rounded-lg focus:ring-1 focus:ring-indigo-500" value={formatCurrency(currentInvoice.discount)} onChange={(e) => { const numeric = parseInt(e.target.value.replace(/\D/g, ''), 10) || 0; setCurrentInvoice({...currentInvoice, discount: numeric}); }} /></div>
                  <div className="border-t border-slate-200 pt-4 flex justify-between items-end"><span className="text-slate-800 font-bold text-lg uppercase tracking-wider">Total Tagihan</span><span className="text-2xl font-serif font-bold text-slate-800">Rp {formatCurrency(calculateTotal(currentInvoice))}</span></div>
                  <div className="border-t border-indigo-200 pt-4 flex justify-between items-end"><span className="text-indigo-800 font-bold text-lg uppercase tracking-wider">Sisa Tagihan</span><span className="text-3xl font-serif font-bold text-indigo-600">Rp {formatCurrency(calculateTotal(currentInvoice) - calculatePaid(currentInvoice))}</span></div>
                </div>
              </div>
            </div>
          </div>
        )}

        {viewMode === 'view' && currentInvoice && (
          <div className="space-y-8 animate-in fade-in duration-500">
             <div className="flex justify-between items-center no-print">
              <button onClick={() => setViewMode('list')} className="flex items-center gap-2 text-slate-500 font-semibold hover:text-slate-800 transition-colors">
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M10 19l-7-7m0 0l7-7m-7 7h18" /></svg>
                Kembali ke Riwayat
              </button>
              <button onClick={() => window.print()} className="bg-slate-800 text-white px-6 py-2.5 rounded-xl font-bold hover:bg-slate-900 transition-all flex items-center gap-2">
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4a2 2 0 00-2-2H9a2 2 0 00-2 2v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z" /></svg>
                Cetak Invoice
              </button>
            </div>
            <InvoicePreview invoice={currentInvoice} settings={settings} />
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useCallback } from 'react';
import { Invoice, ViewMode, InvoiceItem, Payment, HotelSettings } from './types';
import { InvoicePreview } from './components/InvoicePreview';
import { InvoiceItemRow } from './components/InvoiceItemRow';
import { PaymentRow } from './components/PaymentRow';
import { SettingsPage } from './components/SettingsPage';
import { ROOM_TYPES, PAYMENT_METHODS, HOTEL_INFO, TAX_RATE } from './constants';
import { generatePersonalizedNote } from './services/geminiService';

const INITIAL_GUEST = { name: '', email: '', phone: '', address: '' };
const INITIAL_STAY = { roomNumber: '', roomType: ROOM_TYPES[0], checkIn: '', checkOut: '', guestsCount: 1 };

const App: React.FC = () => {
  const [viewMode, setViewMode] = useState<ViewMode>('list');
  const [invoices, setInvoices] = useState<Invoice[]>([]);
  const [currentInvoice, setCurrentInvoice] = useState<Invoice | null>(null);
  const [isGeneratingNote, setIsGeneratingNote] = useState(false);
  const [syncStatus, setSyncStatus] = useState<'idle' | 'syncing' | 'success' | 'error'>('idle');
  const [isMinimized, setIsMinimized] = useState(false);
  const [settings, setSettings] = useState<HotelSettings>({
    ...HOTEL_INFO,
    defaultTaxRate: TAX_RATE,
    googleSheetUrl: ''
  });

  // Load from local storage on mount
  useEffect(() => {
    const savedInvoices = localStorage.getItem('hotelflow_invoices');
    if (savedInvoices) setInvoices(JSON.parse(savedInvoices));

    const savedSettings = localStorage.getItem('hotelflow_settings');
    if (savedSettings) setSettings(JSON.parse(savedSettings));

    const savedDraft = localStorage.getItem('hotelflow_draft');
    if (savedDraft) {
      setCurrentInvoice(JSON.parse(savedDraft));
      setIsMinimized(true);
    }
  }, []);

  // Save invoices to local storage
  useEffect(() => {
    localStorage.setItem('hotelflow_invoices', JSON.stringify(invoices));
  }, [invoices]);

  // Save draft to local storage when minimized
  useEffect(() => {
    if (isMinimized && currentInvoice) {
      localStorage.setItem('hotelflow_draft', JSON.stringify(currentInvoice));
    } else if (!isMinimized) {
      localStorage.removeItem('hotelflow_draft');
    }
  }, [isMinimized, currentInvoice]);

  const syncToCloud = useCallback(async (type: 'settings' | 'invoice', payload: any) => {
    if (!settings.googleSheetUrl) return;

    setSyncStatus('syncing');
    try {
      await fetch(settings.googleSheetUrl, {
        method: 'POST',
        mode: 'no-cors',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ type, payload })
      });
      setSyncStatus('success');
      setTimeout(() => setSyncStatus('idle'), 3000);
    } catch (error) {
      console.error('Auto-sync error:', error);
      setSyncStatus('error');
    }
  }, [settings.googleSheetUrl]);

  const handleSaveSettings = (newSettings: HotelSettings) => {
    setSettings(newSettings);
    localStorage.setItem('hotelflow_settings', JSON.stringify(newSettings));
    syncToCloud('settings', newSettings);
  };

  const calculateTotal = (inv: Invoice) => {
    const subtotal = inv.items.reduce((sum, item) => sum + (item.quantity * item.nights * item.unitPrice), 0);
    return subtotal + (subtotal * inv.taxRate) - inv.discount;
  };

  const calculatePaid = (inv: Invoice) => {
    return inv.payments.reduce((sum, p) => sum + p.amount, 0);
  };

  const formatCurrency = (val: number) => {
    return val.toLocaleString('id-ID');
  };

  const handleSaveInvoice = async () => {
    if (!currentInvoice) return;

    setIsGeneratingNote(true);
    const aiNote = await generatePersonalizedNote(currentInvoice);
    const finalizedInvoice = { ...currentInvoice, aiGreeting: aiNote, hotelSnap: settings };

    setInvoices(prev => {
      const exists = prev.find(i => i.id === finalizedInvoice.id);
      if (exists) {
        return prev.map(i => i.id === finalizedInvoice.id ? finalizedInvoice : i);
      }
      return [finalizedInvoice, ...prev];
    });

    setIsGeneratingNote(false);
    setIsMinimized(false);
    setCurrentInvoice(finalizedInvoice);
    setViewMode('view');

    syncToCloud('invoice', {
      invoiceNumber: finalizedInvoice.invoiceNumber,
      date: finalizedInvoice.date,
      guestName: finalizedInvoice.guest.name,
      roomNumber: finalizedInvoice.stay.roomNumber,
      totalAmount: calculateTotal(finalizedInvoice),
      paidAmount: calculatePaid(finalizedInvoice),
      balanceDue: calculateTotal(finalizedInvoice) - calculatePaid(finalizedInvoice),
      status: finalizedInvoice.status
    });
  };

  const createNewInvoice = () => {
    if (isMinimized && currentInvoice) {
      if (!window.confirm("Ada draft yang sedang di-minimize. Ingin melanjutkan draft tamu " + (currentInvoice.guest.name || "Anonim") + "?\n\nKlik OK untuk lanjut, atau Cancel untuk menghapus draft dan buat baru.")) {
        setIsMinimized(false);
        localStorage.removeItem('hotelflow_draft');
      } else {
        setViewMode('create');
        setIsMinimized(false);
        return;
      }
    }

    const id = Math.random().toString(36).substr(2, 9);
    const newInvoice: Invoice = {
      id,
      invoiceNumber: `INV-${new Date().getFullYear()}-${Math.floor(Math.random() * 9000 + 1000)}`,
      date: new Date().toISOString().split('T')[0],
      guest: { ...INITIAL_GUEST },
      stay: { ...INITIAL_STAY },
      items: [{ id: '1', description: '', quantity: 1, nights: 1, unitPrice: 0, total: 0 }],
      payments: [],
      taxRate: settings.defaultTaxRate,
      discount: 0,
      status: 'draft',
      notes: '',
      hotelSnap: settings
    };
    setCurrentInvoice(newInvoice);
    setViewMode('create');
    setIsMinimized(false);
  };

  const handleMinimize = () => {
    setIsMinimized(true);
    setViewMode('list');
  };

  const handleRestore = () => {
    setIsMinimized(false);
    setViewMode('create');
  };

  const handleUpdateItem = (id: string, updates: Partial<InvoiceItem>) => {
    if (!currentInvoice) return;
    const updatedItems = currentInvoice.items.map(item => item.id === id ? { ...item, ...updates } : item);
    setCurrentInvoice({ ...currentInvoice, items: updatedItems });
  };

  const handleDeleteItem = (id: string) => {
    if (!currentInvoice) return;
    setCurrentInvoice({ ...currentInvoice, items: currentInvoice.items.filter(item => item.id !== id) });
  };

  const addItem = () => {
    if (!currentInvoice) return;
    const newItem: InvoiceItem = { id: Math.random().toString(36).substr(2, 9), description: '', quantity: 1, nights: 1, unitPrice: 0, total: 0 };
    setCurrentInvoice({ ...currentInvoice, items: [...currentInvoice.items, newItem] });
  };

  const handleUpdatePayment = (id: string, updates: Partial<Payment>) => {
    if (!currentInvoice) return;
    const updatedPayments = currentInvoice.payments.map(p => p.id === id ? { ...p, ...updates } : p);
    setCurrentInvoice({ ...currentInvoice, payments: updatedPayments });
  };

  const addPayment = () => {
    if (!currentInvoice) return;
    const newPayment: Payment = { id: Math.random().toString(36).substr(2, 9), date: new Date().toISOString().split('T')[0], method: PAYMENT_METHODS[0], amount: 0 };
    setCurrentInvoice({ ...currentInvoice, payments: [...currentInvoice.payments, newPayment] });
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col">
      {/* Global Cloud Status Indicator */}
      <div className={`fixed bottom-6 left-6 z-[60] px-4 py-2 rounded-2xl text-[10px] font-bold shadow-2xl transition-all duration-500 transform flex items-center gap-3 border ${
        syncStatus === 'syncing' ? 'bg-indigo-600 border-indigo-500 text-white translate-y-0 scale-100' :
        syncStatus === 'success' ? 'bg-emerald-500 border-emerald-400 text-white translate-y-0 scale-100' :
        syncStatus === 'error' ? 'bg-red-500 border-red-400 text-white translate-y-0 scale-100' : 'translate-y-20 opacity-0 scale-90'
      }`}>
        {syncStatus === 'syncing' ? (
          <svg className="animate-spin h-3 w-3 text-white" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg>
        ) : syncStatus === 'success' ? (
          <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M5 13l4 4L19 7" /></svg>
        ) : (
          <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M6 18L18 6M6 6l12 12" /></svg>
        )}
        <span className="uppercase tracking-widest">
          {syncStatus === 'syncing' ? 'Syncing to Cloud...' : syncStatus === 'success' ? 'Spreadsheet Updated' : 'Sync Failed'}
        </span>
      </div>

      {/* Modern Minimize Bar */}
      {isMinimized && currentInvoice && viewMode !== 'create' && (
        <div className="fixed bottom-6 right-6 z-[60] animate-slide-right">
          <div className="bg-white/80 backdrop-blur-xl border border-white/20 shadow-[0_20px_50px_rgba(0,0,0,0.1)] rounded-3xl p-5 flex items-center gap-5 min-w-[320px]">
            <div className="relative">
              <div className="bg-indigo-600 p-3 rounded-2xl shadow-lg shadow-indigo-200">
                <svg className="w-6 h-6 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
                </svg>
              </div>
              <span className="absolute -top-1 -right-1 flex h-3 w-3">
                <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-indigo-400 opacity-75"></span>
                <span className="relative inline-flex rounded-full h-3 w-3 bg-indigo-500"></span>
              </span>
            </div>
            <div className="flex-1 overflow-hidden">
              <p className="text-[10px] font-bold text-indigo-500 uppercase tracking-[0.2em] mb-0.5">Draft Aktif</p>
              <p className="text-sm font-bold text-slate-800 truncate">
                {currentInvoice.guest.name || "Tamu Tanpa Nama"}
              </p>
              <p className="text-[10px] text-slate-400 font-mono">{currentInvoice.invoiceNumber}</p>
            </div>
            <div className="flex items-center gap-2">
              <button 
                onClick={handleRestore}
                className="bg-slate-900 text-white px-4 py-2 rounded-xl text-xs font-bold hover:bg-black transition-all active:scale-95 shadow-lg shadow-slate-200"
              >
                Lanjutkan
              </button>
              <button 
                onClick={() => { if(window.confirm('Hapus draft permanen?')) setIsMinimized(false); }}
                className="p-2 text-slate-300 hover:text-red-500 transition-colors"
                title="Hapus Draft"
              >
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" /></svg>
              </button>
            </div>
          </div>
        </div>
      )}

      <header className="bg-white/80 backdrop-blur-md border-b border-slate-200 sticky top-0 z-50 no-print">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between items-center h-18 py-4">
            <div className="flex items-center gap-10">
              <div className="flex items-center gap-4 cursor-pointer group" onClick={() => setViewMode('list')}>
                <div className="bg-gradient-to-br from-indigo-600 to-violet-700 p-2.5 rounded-2xl shadow-lg shadow-indigo-100 group-hover:scale-110 transition-transform duration-300">
                  <svg className="w-6 h-6 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
