export default App;

import React, { useState, useEffect, useCallback } from 'react';
import { Invoice, ViewMode, InvoiceItem, Payment, HotelSettings } from './types';
import { InvoicePreview } from './components/InvoicePreview';
import { InvoiceItemRow } from './components/InvoiceItemRow';
import { PaymentRow } from './components/PaymentRow';
import { SettingsPage } from './components/SettingsPage';
import { ROOM_TYPES, PAYMENT_METHODS, HOTEL_INFO, TAX_RATE } from './constants';
import { generatePersonalizedNote } from './services/geminiService';

const INITIAL_GUEST = { name: '', email: '', phone: '', address: '' };
const INITIAL_STAY = { roomNumber: '', roomType: ROOM_TYPES[0], checkIn: '', checkOut: '', guestsCount: 1 };

const App: React.FC = () => {
  const [viewMode, setViewMode] = useState<ViewMode>('list');
  const [dashboardTab, setDashboardTab] = useState<'without-tax' | 'with-tax'>('with-tax');
  const [invoices, setInvoices] = useState<Invoice[]>([]);
  const [currentInvoice, setCurrentInvoice] = useState<Invoice | null>(null);
  const [isGeneratingNote, setIsGeneratingNote] = useState(false);
  const [syncStatus, setSyncStatus] = useState<'idle' | 'syncing' | 'success' | 'error'>('idle');
  const [isMinimized, setIsMinimized] = useState(false);
  const [settings, setSettings] = useState<HotelSettings>({
    ...HOTEL_INFO,
    defaultTaxRate: TAX_RATE,
    googleSheetUrl: HOTEL_INFO.googleSheetUrl
  });

  // Load from local storage on mount
  useEffect(() => {
    const savedInvoices = localStorage.getItem('hotelflow_invoices');
    if (savedInvoices) setInvoices(JSON.parse(savedInvoices));

    const savedSettings = localStorage.getItem('hotelflow_settings');
    if (savedSettings) {
      const parsed = JSON.parse(savedSettings);
      if (!parsed.googleSheetUrl) {
        parsed.googleSheetUrl = HOTEL_INFO.googleSheetUrl;
      }
      setSettings(parsed);
    }

    const savedDraft = localStorage.getItem('hotelflow_draft');
    if (savedDraft) {
      setCurrentInvoice(JSON.parse(savedDraft));
      setIsMinimized(true);
    }
  }, []);

  // Save invoices to local storage
  useEffect(() => {
    localStorage.setItem('hotelflow_invoices', JSON.stringify(invoices));
  }, [invoices]);

  // Save draft to local storage when minimized
  useEffect(() => {
    if (isMinimized && currentInvoice) {
      localStorage.setItem('hotelflow_draft', JSON.stringify(currentInvoice));
    } else if (!isMinimized) {
      localStorage.removeItem('hotelflow_draft');
    }
  }, [isMinimized, currentInvoice]);

  const syncToCloud = useCallback(async (type: 'settings' | 'invoice', payload: any) => {
    if (!settings.googleSheetUrl) return;

    setSyncStatus('syncing');
    try {
      await fetch(settings.googleSheetUrl, {
        method: 'POST',
        mode: 'no-cors',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ type, payload })
      });
      setSyncStatus('success');
      setTimeout(() => setSyncStatus('idle'), 3000);
    } catch (error) {
      console.error('Auto-sync error:', error);
      setSyncStatus('error');
    }
  }, [settings.googleSheetUrl]);

  const handleSaveSettings = (newSettings: HotelSettings) => {
    setSettings(newSettings);
    localStorage.setItem('hotelflow_settings', JSON.stringify(newSettings));
    syncToCloud('settings', newSettings);
  };

  const calculateSubtotal = (inv: Invoice) => {
    return inv.items.reduce((sum, item) => sum + (item.quantity * item.nights * item.unitPrice), 0);
  };

  const calculateTax = (inv: Invoice) => {
    return calculateSubtotal(inv) * inv.taxRate;
  };

  const calculateTotal = (inv: Invoice) => {
    const subtotal = calculateSubtotal(inv);
    return subtotal + (subtotal * inv.taxRate) - inv.discount;
  };

  const calculateTotalNoTax = (inv: Invoice) => {
    return calculateSubtotal(inv) - inv.discount;
  };

  const calculatePaid = (inv: Invoice) => {
    return inv.payments.reduce((sum, p) => sum + p.amount, 0);
  };

  const formatCurrency = (val: number) => {
    return val.toLocaleString('id-ID');
  };

  const handleSaveInvoice = async () => {
    if (!currentInvoice) return;

    setIsGeneratingNote(true);
    const aiNote = await generatePersonalizedNote(currentInvoice);
    const finalizedInvoice = { ...currentInvoice, aiGreeting: aiNote, hotelSnap: settings };

    setInvoices(prev => {
      const exists = prev.find(i => i.id === finalizedInvoice.id);
      if (exists) {
        return prev.map(i => i.id === finalizedInvoice.id ? finalizedInvoice : i);
      }
      return [finalizedInvoice, ...prev];
    });

    setIsGeneratingNote(false);
    setIsMinimized(false);
    setCurrentInvoice(finalizedInvoice);
    setViewMode('view');

    syncToCloud('invoice', {
      invoiceNumber: finalizedInvoice.invoiceNumber,
      date: finalizedInvoice.date,
      guestName: finalizedInvoice.guest.name,
      roomNumber: finalizedInvoice.stay.roomNumber,
      totalAmount: calculateTotal(finalizedInvoice),
      paidAmount: calculatePaid(finalizedInvoice),
      balanceDue: calculateTotal(finalizedInvoice) - calculatePaid(finalizedInvoice),
      status: finalizedInvoice.status
    });
  };

  const createNewInvoice = () => {
    if (isMinimized && currentInvoice) {
      if (!window.confirm("Ada draft yang sedang di-minimize. Ingin melanjutkan draft tamu " + (currentInvoice.guest.name || "Anonim") + "?\n\nKlik OK untuk lanjut, atau Cancel untuk menghapus draft dan buat baru.")) {
        setIsMinimized(false);
        localStorage.removeItem('hotelflow_draft');
      } else {
        setViewMode('create');
        setIsMinimized(false);
        return;
      }
    }

    const id = Math.random().toString(36).substr(2, 9);
    const newInvoice: Invoice = {
      id,
      invoiceNumber: `INV-${new Date().getFullYear()}-${Math.floor(Math.random() * 9000 + 1000)}`,
      date: new Date().toISOString().split('T')[0],
      guest: { ...INITIAL_GUEST },
      stay: { ...INITIAL_STAY },
      items: [{ id: '1', description: '', quantity: 1, nights: 1, unitPrice: 0, total: 0 }],
      payments: [],
      taxRate: settings.defaultTaxRate,
      discount: 0,
      status: 'draft',
      notes: '',
      hotelSnap: settings
    };
    setCurrentInvoice(newInvoice);
    setViewMode('create');
    setIsMinimized(false);
  };

  const handleMinimize = () => {
    setIsMinimized(true);
    setViewMode('list');
  };

  const handleRestore = () => {
    setIsMinimized(false);
    setViewMode('create');
  };

  const handleUpdateItem = (id: string, updates: Partial<InvoiceItem>) => {
    if (!currentInvoice) return;
    const updatedItems = currentInvoice.items.map(item => item.id === id ? { ...item, ...updates } : item);
    setCurrentInvoice({ ...currentInvoice, items: updatedItems });
  };

  const handleDeleteItem = (id: string) => {
    if (!currentInvoice) return;
    setCurrentInvoice({ ...currentInvoice, items: currentInvoice.items.filter(item => item.id !== id) });
  };

  const addItem = () => {
    if (!currentInvoice) return;
    const newItem: InvoiceItem = { id: Math.random().toString(36).substr(2, 9), description: '', quantity: 1, nights: 1, unitPrice: 0, total: 0 };
    setCurrentInvoice({ ...currentInvoice, items: [...currentInvoice.items, newItem] });
  };

  const handleUpdatePayment = (id: string, updates: Partial<Payment>) => {
    if (!currentInvoice) return;
    const updatedPayments = currentInvoice.payments.map(p => p.id === id ? { ...p, ...updates } : p);
    setCurrentInvoice({ ...currentInvoice, payments: updatedPayments });
  };

  const addPayment = () => {
    if (!currentInvoice) return;
    const newPayment: Payment = { id: Math.random().toString(36).substr(2, 9), date: new Date().toISOString().split('T')[0], method: PAYMENT_METHODS[0], amount: 0 };
    setCurrentInvoice({ ...currentInvoice, payments: [...currentInvoice.payments, newPayment] });
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col">
      {/* Sync Status Indicator */}
      <div className={`fixed bottom-6 left-6 z-[60] px-4 py-2 rounded-2xl text-[10px] font-bold shadow-2xl transition-all duration-500 transform flex items-center gap-3 border ${
        syncStatus === 'syncing' ? 'bg-indigo-600 border-indigo-500 text-white translate-y-0 scale-100' :
        syncStatus === 'success' ? 'bg-emerald-500 border-emerald-400 text-white translate-y-0 scale-100' :
        syncStatus === 'error' ? 'bg-red-500 border-red-400 text-white translate-y-0 scale-100' : 'translate-y-20 opacity-0 scale-90'
      }`}>
        <span className="uppercase tracking-widest">
          {syncStatus === 'syncing' ? 'Cloud Syncing...' : syncStatus === 'success' ? 'Cloud Connected' : 'Sync Error'}
        </span>
      </div>

      {/* Minimize Bar */}
      {isMinimized && currentInvoice && viewMode !== 'create' && (
        <div className="fixed bottom-6 right-6 z-[60] animate-slide-right">
          <div className="bg-white/80 backdrop-blur-xl border border-indigo-100 shadow-2xl rounded-3xl p-5 flex items-center gap-5 min-w-[320px]">
            <div className="bg-indigo-600 p-3 rounded-2xl shadow-lg shadow-indigo-200">
              <svg className="w-6 h-6 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" /></svg>
            </div>
            <div className="flex-1 overflow-hidden">
              <p className="text-[10px] font-bold text-indigo-500 uppercase tracking-widest mb-0.5">Draft Aktif</p>
              <p className="text-sm font-bold text-slate-800 truncate">{currentInvoice.guest.name || "Tamu Tanpa Nama"}</p>
            </div>
            <button onClick={handleRestore} className="bg-slate-900 text-white px-4 py-2 rounded-xl text-xs font-bold hover:bg-black transition-all shadow-lg">Lanjutkan</button>
          </div>
        </div>
      )}

      <header className="bg-white/80 backdrop-blur-md border-b border-slate-200 sticky top-0 z-50 no-print">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between items-center h-20">
            <div className="flex items-center gap-10">
              <div className="flex items-center gap-3 cursor-pointer group" onClick={() => setViewMode('list')}>
                <div className="bg-indigo-600 p-2 rounded-xl shadow-lg shadow-indigo-100 group-hover:scale-110 transition-transform">
                  <svg className="w-6 h-6 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 21V5a2 2 0 00-2-2H7a2 2 0 00-2 2v16m14 0h2m-2 0h-5m-9 0H3m2 0h5M9 7h1m-1 4h1m4-4h1m-1 4h1m-5 10v-5a1 1 0 011-1h2a1 1 0 011 1v5m-4 0h4" /></svg>
                </div>
                <h1 className="text-xl font-bold text-slate-900 tracking-tight">HotelFlow</h1>
              </div>
              <nav className="hidden md:flex items-center gap-2">
                <button onClick={() => setViewMode('list')} className={`px-5 py-2 rounded-xl text-sm font-bold transition-all ${viewMode === 'list' ? 'bg-slate-900 text-white' : 'text-slate-500 hover:text-slate-900 hover:bg-slate-100'}`}>Beranda</button>
                <button onClick={() => setViewMode('settings')} className={`px-5 py-2 rounded-xl text-sm font-bold transition-all ${viewMode === 'settings' ? 'bg-slate-900 text-white' : 'text-slate-500 hover:text-slate-900 hover:bg-slate-100'}`}>Settings</button>
              </nav>
            </div>
            <button onClick={createNewInvoice} className="bg-indigo-600 text-white px-6 py-3 rounded-2xl font-bold hover:bg-indigo-700 transition-all shadow-xl shadow-indigo-100 flex items-center gap-2 active:scale-95">
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 4v16m8-8H4" /></svg>
              <span>Buat Invoice</span>
            </button>
          </div>
        </div>
      </header>

      <main className="flex-1 max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-10 w-full">
        {viewMode === 'settings' && <SettingsPage settings={settings} onSave={handleSaveSettings} />}

        {viewMode === 'list' && (
          <div className="animate-slide-up space-y-10">
            <div className="flex flex-col md:flex-row justify-between items-start md:items-end gap-6">
              <div>
                <h2 className="text-3xl font-bold text-slate-900">Dashboard Tagihan</h2>
                <p className="text-slate-500 mt-1">Kelola dan pantau seluruh transaksi hotel Anda.</p>
              </div>

              <div className="bg-slate-200 p-1.5 rounded-2xl flex items-center shadow-inner">
                <button 
                  onClick={() => setDashboardTab('without-tax')}
                  className={`px-6 py-2.5 rounded-xl text-xs font-bold uppercase tracking-widest transition-all ${dashboardTab === 'without-tax' ? 'bg-white text-slate-900 shadow-md' : 'text-slate-500 hover:text-slate-700'}`}
                >
                  Dasar (Tanpa Pajak)
                </button>
                <button 
                  onClick={() => setDashboardTab('with-tax')}
                  className={`px-6 py-2.5 rounded-xl text-xs font-bold uppercase tracking-widest transition-all ${dashboardTab === 'with-tax' ? 'bg-white text-indigo-600 shadow-md' : 'text-slate-500 hover:text-slate-700'}`}
                >
                  Netto (Dengan Pajak)
                </button>
              </div>
            </div>

            {invoices.length === 0 ? (
              <div className="bg-white border-2 border-dashed border-slate-200 rounded-[40px] p-24 text-center">
                <div className="bg-slate-50 w-24 h-24 rounded-full flex items-center justify-center mx-auto mb-8">
                  <svg className="w-12 h-12 text-slate-300" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="1" d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" /></svg>
                </div>
                <h3 className="text-2xl font-bold text-slate-800 mb-2">Belum ada riwayat</h3>
                <p className="text-slate-400 mb-10 max-w-sm mx-auto">Mulai buat invoice pertama Anda untuk mencatat transaksi.</p>
              </div>
            ) : (
              <div className="bg-white shadow-xl shadow-slate-200/50 border border-slate-200 rounded-[32px] overflow-hidden">
                <div className="p-8 border-b border-slate-50 flex justify-between items-center bg-slate-50/30">
                  <h3 className="font-bold text-slate-800 flex items-center gap-3">
                    <span className={`w-2 h-2 rounded-full ${dashboardTab === 'with-tax' ? 'bg-indigo-500' : 'bg-slate-400'}`}></span>
                    {dashboardTab === 'with-tax' ? 'Rekapitulasi Invoice Termasuk PPN 11%' : 'Rekapitulasi Nilai Dasar Layanan'}
                  </h3>
                  <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Total: {invoices.length} Transaksi</span>
                </div>
                <table className="w-full text-left">
                  <thead className="bg-slate-50/50 border-b border-slate-100">
                    <tr>
                      <th className="px-8 py-5 text-[11px] font-bold uppercase text-slate-400 tracking-[0.2em]">ID Invoice</th>
                      <th className="px-8 py-5 text-[11px] font-bold uppercase text-slate-400 tracking-[0.2em]">Nama Tamu</th>
                      <th className="px-8 py-5 text-[11px] font-bold uppercase text-slate-400 tracking-[0.2em] text-right">
                        {dashboardTab === 'with-tax' ? 'Subtotal' : 'Murni Layanan'}
                      </th>
                      {dashboardTab === 'with-tax' && (
                        <th className="px-8 py-5 text-[11px] font-bold uppercase text-slate-400 tracking-[0.2em] text-right">PPN 11%</th>
                      )}
                      <th className="px-8 py-5 text-[11px] font-bold uppercase text-slate-400 tracking-[0.2em] text-right">Grand Total</th>
                      <th className="px-8 py-5 text-[11px] font-bold uppercase text-slate-400 tracking-[0.2em] text-right">Aksi</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-50">
                    {invoices.map((inv) => (
                      <tr key={inv.id} className="hover:bg-slate-50/80 transition-colors group">
                        <td className="px-8 py-5 font-mono text-xs text-indigo-600 font-bold">{inv.invoiceNumber}</td>
                        <td className="px-8 py-5">
                          <div className="font-bold text-slate-800">{inv.guest.name}</div>
                          <div className="text-[10px] text-slate-400 uppercase tracking-wider">{inv.stay.roomType} / RM {inv.stay.roomNumber}</div>
                        </td>
                        <td className="px-8 py-5 text-right font-medium text-slate-600">
                          Rp {formatCurrency(calculateSubtotal(inv))}
                        </td>
                        {dashboardTab === 'with-tax' && (
                          <td className="px-8 py-5 text-right font-medium text-indigo-400">
                            +Rp {formatCurrency(calculateTax(inv))}
                          </td>
                        )}
                        <td className="px-8 py-5 text-right font-bold text-slate-900">
                          Rp {formatCurrency(dashboardTab === 'with-tax' ? calculateTotal(inv) : calculateTotalNoTax(inv))}
                        </td>
                        <td className="px-8 py-5 text-right">
                          <div className="flex justify-end gap-3 opacity-0 group-hover:opacity-100 transition-opacity">
                            <button onClick={() => { setCurrentInvoice(inv); setViewMode('view'); }} className="p-2 bg-white border border-slate-200 rounded-lg text-slate-500 hover:text-indigo-600"><svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z" /></svg></button>
                            <button onClick={() => { setCurrentInvoice(inv); setViewMode('create'); }} className="p-2 bg-white border border-slate-200 rounded-lg text-slate-500 hover:text-amber-600"><svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M11 5H6a2 2 0 00-2 2v11a2 2 0 00-2 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z" /></svg></button>
                          </div>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </div>
        )}

        {viewMode === 'create' && currentInvoice && (
          <div className="animate-zoom-in bg-white shadow-2xl rounded-[40px] overflow-hidden border border-slate-200">
            {/* Form Header */}
            <div className="p-10 border-b border-slate-100 flex justify-between items-center bg-slate-50/30">
              <div className="flex items-center gap-6">
                <button onClick={handleMinimize} className="p-3 bg-white border border-slate-200 text-slate-400 hover:text-indigo-600 rounded-2xl shadow-sm transition-all" title="Minimize Draft">
                  <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M20 12H4" /></svg>
                </button>
                <div>
                  <h2 className="text-2xl font-bold text-slate-900 leading-tight">Billing Workspace</h2>
                  <div className="flex items-center gap-2 mt-1">
                    <span className="text-indigo-500 font-mono text-sm font-bold uppercase tracking-wider">{currentInvoice.invoiceNumber}</span>
                  </div>
                </div>
              </div>
              <div className="flex gap-4">
                <button onClick={() => setViewMode('list')} className="px-8 py-3 text-slate-500 font-bold hover:text-slate-900">Batal</button>
                <button onClick={handleSaveInvoice} disabled={isGeneratingNote} className="bg-indigo-600 text-white px-10 py-3 rounded-2xl font-bold hover:bg-indigo-700 transition-all shadow-xl shadow-indigo-200 flex items-center gap-3 active:scale-95 disabled:opacity-50">
                  {isGeneratingNote ? 'AI Processing...' : 'Finalize & Cloud Sync'}
                </button>
              </div>
            </div>

            <div className="p-12 space-y-12">
              {/* SECTION 1: Guest & Stay Info */}
              <section className="space-y-8">
                <h3 className="text-xs font-bold text-slate-400 uppercase tracking-[0.3em] flex items-center gap-4">
                  Informasi Tamu & Menginap
                  <div className="h-px bg-slate-100 flex-1"></div>
                </h3>

                <div className="grid grid-cols-12 gap-8 bg-slate-50/50 p-8 rounded-[32px] border border-slate-100 shadow-inner">
                  <div className="col-span-12 lg:col-span-5 space-y-2">
                    <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest px-1">Nama Lengkap Tamu</label>
                    <input type="text" placeholder="GUEST FULL NAME" className="w-full px-5 py-4 border border-slate-200 rounded-2xl focus:ring-4 focus:ring-indigo-50 focus:border-indigo-600 outline-none transition-all font-bold uppercase tracking-wide bg-white" value={currentInvoice.guest.name} onChange={(e) => setCurrentInvoice({...currentInvoice, guest: {...currentInvoice.guest, name: e.target.value.toUpperCase()}})} />
                  </div>

                  <div className="col-span-12 lg:col-span-4 space-y-2">
                    <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest px-1">Email / Kontak</label>
                    <input type="email" placeholder="email@address.com" className="w-full px-5 py-4 border border-slate-200 rounded-2xl focus:ring-4 focus:ring-indigo-50 focus:border-indigo-600 outline-none transition-all bg-white" value={currentInvoice.guest.email} onChange={(e) => setCurrentInvoice({...currentInvoice, guest: {...currentInvoice.guest, email: e.target.value}})} />
                  </div>

                  <div className="col-span-12 lg:col-span-3 space-y-2">
                    <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest px-1">Room Class</label>
                    <select className="w-full px-5 py-4 border border-slate-200 rounded-2xl bg-white font-bold outline-none appearance-none cursor-pointer" value={currentInvoice.stay.roomType} onChange={(e) => setCurrentInvoice({...currentInvoice, stay: {...currentInvoice.stay, roomType: e.target.value}})}>
                      {ROOM_TYPES.map(type => <option key={type} value={type}>{type}</option>)}
                    </select>
                  </div>

                  <div className="col-span-12 lg:col-span-5 space-y-2">
                    <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest px-1">Alamat Domisili</label>
                    <textarea placeholder="Residential Address" rows={1} className="w-full px-5 py-4 border border-slate-200 rounded-2xl focus:ring-4 focus:ring-indigo-50 focus:border-indigo-600 outline-none transition-all bg-white resize-none" value={currentInvoice.guest.address} onChange={(e) => setCurrentInvoice({...currentInvoice, guest: {...currentInvoice.guest, address: e.target.value}})} />
                  </div>

                  <div className="col-span-4 lg:col-span-2 space-y-2">
                    <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest px-1">No Kamar</label>
                    <input type="text" placeholder="RM #" className="w-full px-5 py-4 border border-slate-200 rounded-2xl focus:ring-4 focus:ring-indigo-50 outline-none bg-white font-bold text-center" value={currentInvoice.stay.roomNumber} onChange={(e) => setCurrentInvoice({...currentInvoice, stay: {...currentInvoice.stay, roomNumber: e.target.value}})} />
                  </div>

                  <div className="col-span-4 lg:col-span-2.5 space-y-2">
                    <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest px-1">Check-in</label>
                    <input type="date" className="w-full px-5 py-4 border border-slate-200 rounded-2xl bg-white outline-none" value={currentInvoice.stay.checkIn} onChange={(e) => setCurrentInvoice({...currentInvoice, stay: {...currentInvoice.stay, checkIn: e.target.value}})} />
                  </div>

                  <div className="col-span-4 lg:col-span-2.5 space-y-2">
                    <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest px-1">Check-out</label>
                    <input type="date" className="w-full px-5 py-4 border border-slate-200 rounded-2xl bg-white outline-none" value={currentInvoice.stay.checkOut} onChange={(e) => setCurrentInvoice({...currentInvoice, stay: {...currentInvoice.stay, checkOut: e.target.value}})} />
                  </div>
                </div>
              </section>

              {/* SECTION 2: Service Inventory - SEPARATE FULL GRID */}
              <section className="space-y-6">
                <div className="flex justify-between items-center">
                  <h3 className="text-xs font-bold text-slate-400 uppercase tracking-[0.3em] flex items-center gap-4 flex-1">
                    Inventaris Layanan Terinci
                    <div className="h-px bg-slate-100 flex-1"></div>
                  </h3>
                  <button onClick={addItem} className="text-xs font-bold text-indigo-600 hover:bg-indigo-50 px-5 py-2.5 rounded-2xl transition-all flex items-center gap-2 group border border-indigo-100 bg-white ml-6">
                    <svg className="w-4 h-4 group-hover:scale-125 transition-transform" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M12 4v16m8-8H4" /></svg>
                    Tambah Layanan Baru
                  </button>
                </div>
                <div className="bg-white border border-slate-200 rounded-[32px] p-8 shadow-sm">
                  <div className="space-y-2">
                    {currentInvoice.items.map(item => (<InvoiceItemRow key={item.id} item={item} onUpdate={handleUpdateItem} onDelete={handleDeleteItem} />))}
                  </div>
                </div>
              </section>

              {/* SECTION 3: Payments - SEPARATE FULL GRID */}
              <section className="space-y-6">
                <div className="flex justify-between items-center">
                  <h3 className="text-xs font-bold text-emerald-500 uppercase tracking-[0.3em] flex items-center gap-4 flex-1">
                    Data Riwayat Pembayaran
                    <div className="h-px bg-emerald-50 flex-1"></div>
                  </h3>
                  <button onClick={addPayment} className="text-xs font-bold text-emerald-600 hover:bg-emerald-50 px-5 py-2.5 rounded-2xl transition-all flex items-center gap-2 group border border-emerald-100 bg-white ml-6">
                    <svg className="w-4 h-4 group-hover:scale-125 transition-transform" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M12 4v16m8-8H4" /></svg>
                    Catat Bayar / Deposit
                  </button>
                </div>
                <div className="bg-white border border-emerald-100 rounded-[32px] p-8 shadow-sm">
                  <div className="space-y-2">
                    {currentInvoice.payments.map(p => (<PaymentRow key={p.id} payment={p} onUpdate={handleUpdatePayment} onDelete={(id) => setCurrentInvoice({...currentInvoice, payments: currentInvoice.payments.filter(pay => pay.id !== id)})} />))}
                  </div>
                </div>
              </section>

              {/* SECTION 4: Summary / Totals Column - SEPARATE FULL HORIZONTAL GRID */}
              <section className="space-y-6">
                <h3 className="text-xs font-bold text-indigo-400 uppercase tracking-[0.3em] flex items-center gap-4">
                  Finalisasi & Ringkasan Tagihan
                  <div className="h-px bg-indigo-50 flex-1"></div>
                </h3>
                <div className="bg-slate-900 rounded-[40px] p-12 text-white shadow-2xl shadow-slate-300 relative overflow-hidden group">
                  <div className="absolute top-0 right-0 w-64 h-64 bg-indigo-600/10 rounded-full -mr-32 -mt-32 blur-3xl group-hover:bg-indigo-600/20 transition-all duration-700"></div>

                  <div className="grid grid-cols-1 md:grid-cols-3 gap-12 relative z-10">
                    <div className="space-y-6">
                      <div className="space-y-2">
                        <p className="text-[10px] font-bold text-indigo-400 uppercase tracking-[0.3em]">Komponen Dasar</p>
                        <div className="flex justify-between items-center text-slate-300 text-sm font-medium">
                          <span>Subtotal Layanan</span>
                          <span>Rp {formatCurrency(calculateSubtotal(currentInvoice))}</span>
                        </div>
                        <div className="flex justify-between items-center text-slate-300 text-sm font-medium">
                          <span>Potongan / Diskon</span>
                          <div className="flex items-center gap-2">
                            <span className="text-rose-400">-</span>
                            <input type="text" className="w-28 bg-white/10 border border-white/20 rounded-lg px-2 py-1 text-right outline-none text-white font-bold text-sm focus:bg-white/20 transition-all" value={formatCurrency(currentInvoice.discount)} onChange={(e) => { const numeric = parseInt(e.target.value.replace(/\D/g, ''), 10) || 0; setCurrentInvoice({...currentInvoice, discount: numeric}); }} />
                          </div>
                        </div>
                      </div>
                      <div className="h-px bg-white/10"></div>
                      <div className="space-y-1">
                        <p className="text-[10px] font-bold text-slate-500 uppercase tracking-[0.2em] italic">Catatan Sistem</p>
                        <p className="text-[10px] text-slate-400 leading-relaxed">* PPN 11% otomatis disertakan di printout.</p>
                      </div>
                    </div>

                    <div className="flex flex-col justify-center items-center md:border-x border-white/10 px-8">
                      <div className="text-center">
                        <p className="text-[11px] font-bold text-indigo-400 uppercase tracking-[0.4em] mb-4">Total Akhir (Netto)</p>
                        <h4 className="text-5xl font-serif font-bold text-white tracking-tight">Rp {formatCurrency(calculateTotal(currentInvoice))}</h4>
                        <div className="mt-6 flex justify-center gap-3">
                          <span className="px-4 py-1.5 rounded-full bg-white/5 border border-white/10 text-[10px] font-bold uppercase tracking-widest text-emerald-400">Pajak Aktif: 11%</span>
                        </div>
                      </div>
                    </div>

                    <div className="flex flex-col justify-between">
                      <div className="text-right space-y-1">
                        <p className="text-[11px] font-bold text-rose-400 uppercase tracking-[0.4em]">Sisa Tagihan (Due)</p>
                        <h4 className="text-4xl font-serif font-bold text-rose-500">Rp {formatCurrency(calculateTotal(currentInvoice) - calculatePaid(currentInvoice))}</h4>
                      </div>

                      <div className="pt-8">
                        <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest mb-3 block text-right">Set Status Transaksi</label>
                        <div className="flex justify-end gap-2">
                          {(['draft', 'paid', 'cancelled'] as const).map(st => (
                            <button key={st} onClick={() => setCurrentInvoice({...currentInvoice, status: st})} className={`px-4 py-2 rounded-xl text-[10px] font-bold uppercase transition-all shadow-lg ${currentInvoice.status === st ? 'bg-indigo-600 text-white ring-2 ring-indigo-400 ring-offset-4 ring-offset-slate-900 scale-105' : 'bg-white/5 text-slate-400 hover:bg-white/10'}`}>
                              {st}
                            </button>
                          ))}
                        </div>
                      </div>
                    </div>
                  </div>
                </div>
              </section>
            </div>
          </div>
        )}

        {viewMode === 'view' && currentInvoice && (
          <div className="animate-slide-up space-y-10 pb-20">
             <div className="flex justify-between items-center no-print bg-white p-5 rounded-[24px] border border-slate-200 shadow-sm">
              <button onClick={() => setViewMode('list')} className="flex items-center gap-3 text-slate-500 font-bold hover:text-slate-900 transition-colors px-4 py-2">
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M10 19l-7-7m0 0l7-7m-7 7h18" /></svg>
                Dashboard
              </button>
              <div className="flex gap-4">
                <button onClick={() => { setViewMode('create'); setIsMinimized(false); }} className="px-6 py-3 border border-slate-200 rounded-2xl font-bold text-slate-600 hover:bg-slate-50">Edit Kembali</button>
                <button onClick={() => window.print()} className="bg-slate-900 text-white px-8 py-3 rounded-2xl font-bold hover:bg-black transition-all flex items-center gap-3 shadow-xl active:scale-95">
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4a2 2 0 00-2-2H9a2 2 0 00-2 2v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z" /></svg>
                  Cetak Invoice
                </button>
              </div>
            </div>
            <InvoicePreview invoice={currentInvoice} settings={settings} />
          </div>
        )}
      </main>

      <footer className="bg-white border-t border-slate-200 py-10 no-print mt-auto">
        <div className="max-w-7xl mx-auto px-4 flex justify-between items-center">
          <p className="text-slate-400 text-xs font-medium uppercase tracking-[0.2em]">&copy; 2024 HotelFlow Invoicing — Blue Orchid Family Hotel & Cottage</p>
          <div className="flex gap-8 text-slate-400">
             <span className="text-xs uppercase tracking-widest">Database Cloud: <span className={settings.googleSheetUrl ? 'text-emerald-500' : 'text-rose-500'}>{settings.googleSheetUrl ? 'Aktif' : 'Terputus'}</span></span>
          </div>
        </div>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useCallback } from 'react';
import { Invoice, ViewMode, InvoiceItem, Payment, HotelSettings } from './types';
import { InvoicePreview } from './components/InvoicePreview';
import { InvoiceItemRow } from './components/InvoiceItemRow';
import { PaymentRow } from './components/PaymentRow';
import { SettingsPage } from './components/SettingsPage';
import { ROOM_TYPES, PAYMENT_METHODS, HOTEL_INFO, TAX_RATE } from './constants';
import { generatePersonalizedNote } from './services/geminiService';

const INITIAL_GUEST = { name: '', email: '', phone: '', address: '' };
const INITIAL_STAY = { roomNumber: '', roomType: ROOM_TYPES[0], checkIn: '', checkOut: '', guestsCount: 1 };

const App: React.FC = () => {
  const [viewMode, setViewMode] = useState<ViewMode>('list');
  const [dashboardTab, setDashboardTab] = useState<'without-tax' | 'with-tax'>('with-tax');
  const [invoices, setInvoices] = useState<Invoice[]>([]);
  const [currentInvoice, setCurrentInvoice] = useState<Invoice | null>(null);
  const [isGeneratingNote, setIsGeneratingNote] = useState(false);
  const [syncStatus, setSyncStatus] = useState<'idle' | 'syncing' | 'success' | 'error'>('idle');
  const [isMinimized, setIsMinimized] = useState(false);
  const [settings, setSettings] = useState<HotelSettings>({
    ...HOTEL_INFO,
    defaultTaxRate: TAX_RATE,
    googleSheetUrl: HOTEL_INFO.googleSheetUrl
  });

  useEffect(() => {
    const savedInvoices = localStorage.getItem('hotelflow_invoices');
    if (savedInvoices) setInvoices(JSON.parse(savedInvoices));
    const savedSettings = localStorage.getItem('hotelflow_settings');
    if (savedSettings) setSettings(JSON.parse(savedSettings));
    const savedDraft = localStorage.getItem('hotelflow_draft');
    if (savedDraft) {
      setCurrentInvoice(JSON.parse(savedDraft));
      setIsMinimized(true);
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('hotelflow_invoices', JSON.stringify(invoices));
  }, [invoices]);

  useEffect(() => {
    if (isMinimized && currentInvoice) {
      localStorage.setItem('hotelflow_draft', JSON.stringify(currentInvoice));
    } else if (!isMinimized) {
      localStorage.removeItem('hotelflow_draft');
    }
  }, [isMinimized, currentInvoice]);

  const syncToCloud = useCallback(async (type: 'settings' | 'invoice', payload: any) => {
    if (!settings.googleSheetUrl) return;
    setSyncStatus('syncing');
    try {
      await fetch(settings.googleSheetUrl, {
        method: 'POST',
        mode: 'no-cors',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ type, payload })
      });
      setSyncStatus('success');
      setTimeout(() => setSyncStatus('idle'), 3000);
    } catch (error) {
      setSyncStatus('error');
    }
  }, [settings.googleSheetUrl]);

  const handleSaveSettings = (newSettings: HotelSettings) => {
    setSettings(newSettings);
    localStorage.setItem('hotelflow_settings', JSON.stringify(newSettings));
    syncToCloud('settings', newSettings);
  };

  const calculateSubtotal = (inv: Invoice) => inv.items.reduce((sum, item) => sum + (item.quantity * item.nights * item.unitPrice), 0);
  const calculateTax = (inv: Invoice) => calculateSubtotal(inv) * inv.taxRate;
  const calculateTotal = (inv: Invoice) => calculateSubtotal(inv) + calculateTax(inv) - inv.discount;
  const calculateTotalNoTax = (inv: Invoice) => calculateSubtotal(inv) - inv.discount;
  const calculatePaid = (inv: Invoice) => inv.payments.reduce((sum, p) => sum + p.amount, 0);
  const formatCurrency = (val: number) => val.toLocaleString('id-ID');

  const handleSaveInvoice = async () => {
    if (!currentInvoice) return;
    setIsGeneratingNote(true);
    const aiNote = await generatePersonalizedNote(currentInvoice);
    const finalizedInvoice = { ...currentInvoice, aiGreeting: aiNote, hotelSnap: settings };
    setInvoices(prev => {
      const exists = prev.find(i => i.id === finalizedInvoice.id);
      return exists ? prev.map(i => i.id === finalizedInvoice.id ? finalizedInvoice : i) : [finalizedInvoice, ...prev];
    });
    setIsGeneratingNote(false);
    setIsMinimized(false);
    setCurrentInvoice(finalizedInvoice);
    setViewMode('view');
    syncToCloud('invoice', {
      invoiceNumber: finalizedInvoice.invoiceNumber,
      date: finalizedInvoice.date,
      guestName: finalizedInvoice.guest.name,
      totalAmount: calculateTotal(finalizedInvoice),
      status: finalizedInvoice.status
    });
  };

  const createNewInvoice = () => {
    const id = Math.random().toString(36).substr(2, 9);
    setCurrentInvoice({
      id,
      invoiceNumber: `INV-${new Date().getFullYear()}-${Math.floor(Math.random() * 9000 + 1000)}`,
      date: new Date().toISOString().split('T')[0],
      guest: { ...INITIAL_GUEST },
      stay: { ...INITIAL_STAY },
      items: [{ id: '1', description: '', quantity: 1, nights: 1, unitPrice: 0, total: 0 }],
      payments: [],
      taxRate: settings.defaultTaxRate,
      discount: 0,
      status: 'draft',
      notes: '',
      hotelSnap: settings
    });
    setViewMode('create');
    setIsMinimized(false);
  };

  const handleUpdateItem = (id: string, updates: Partial<InvoiceItem>) => {
    if (!currentInvoice) return;
    setCurrentInvoice({ ...currentInvoice, items: currentInvoice.items.map(item => item.id === id ? { ...item, ...updates } : item) });
  };

  const handleUpdatePayment = (id: string, updates: Partial<Payment>) => {
    if (!currentInvoice) return;
    setCurrentInvoice({ ...currentInvoice, payments: currentInvoice.payments.map(p => p.id === id ? { ...p, ...updates } : p) });
  };

  return (
    <div className="h-screen bg-slate-50 flex flex-col overflow-hidden">
      {/* Header - Slim */}
      <header className="bg-white border-b border-slate-200 h-16 shrink-0 flex items-center z-50 no-print">
        <div className="max-w-[1600px] w-full mx-auto px-6 flex justify-between items-center">
          <div className="flex items-center gap-6">
            <div className="flex items-center gap-2 cursor-pointer" onClick={() => setViewMode('list')}>
              <div className="bg-indigo-600 p-1.5 rounded-lg">
                <svg className="w-5 h-5 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 21V5a2 2 0 00-2-2H7a2 2 0 00-2 2v16m14 0h2m-2 0h-5m-9 0H3m2 0h5M9 7h1m-1 4h1m4-4h1m-1 4h1m-5 10v-5a1 1 0 011-1h2a1 1 0 011 1v5m-4 0h4" /></svg>
              </div>
              <h1 className="text-lg font-bold text-slate-900">HotelFlow</h1>
            </div>
            <nav className="flex items-center gap-1">
              <button onClick={() => setViewMode('list')} className={`px-4 py-1.5 rounded-lg text-xs font-bold ${viewMode === 'list' ? 'bg-slate-900 text-white' : 'text-slate-500'}`}>Beranda</button>
              <button onClick={() => setViewMode('settings')} className={`px-4 py-1.5 rounded-lg text-xs font-bold ${viewMode === 'settings' ? 'bg-slate-900 text-white' : 'text-slate-500'}`}>Settings</button>
            </nav>
          </div>
          <button onClick={createNewInvoice} className="bg-indigo-600 text-white px-5 py-2 rounded-xl text-sm font-bold shadow-lg hover:bg-indigo-700 active:scale-95 transition-all flex items-center gap-2">
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 4v16m8-8H4" /></svg>
            Buat Invoice
          </button>
        </div>
      </header>

      {/* Main Area */}
      <main className="flex-1 overflow-hidden flex flex-col relative">
        {viewMode === 'list' && (
          <div className="flex-1 overflow-y-auto p-6 max-w-[1600px] w-full mx-auto">
            <div className="flex justify-between items-end mb-6">
              <h2 className="text-2xl font-bold text-slate-900">Dashboard</h2>
              <div className="bg-slate-200 p-1 rounded-xl flex shadow-inner">
                {['without-tax', 'with-tax'].map(t => (
                  <button key={t} onClick={() => setDashboardTab(t as any)} className={`px-4 py-1.5 rounded-lg text-[10px] font-bold uppercase transition-all ${dashboardTab === t ? 'bg-white text-slate-900 shadow' : 'text-slate-500'}`}>
                    {t === 'with-tax' ? 'Dengan Pajak' : 'Tanpa Pajak'}
                  </button>
                ))}
              </div>
            </div>
            <div className="bg-white border border-slate-200 rounded-3xl shadow-sm overflow-hidden">
              <table className="w-full text-left text-sm">
                <thead className="bg-slate-50 border-b border-slate-100">
                  <tr>
                    <th className="px-6 py-4 font-bold text-slate-400 text-[10px] uppercase">ID Invoice</th>
                    <th className="px-6 py-4 font-bold text-slate-400 text-[10px] uppercase">Tamu</th>
                    <th className="px-6 py-4 font-bold text-slate-400 text-[10px] uppercase text-right">Total</th>
                    <th className="px-6 py-4 font-bold text-slate-400 text-[10px] uppercase">Status</th>
                    <th className="px-6 py-4 text-right">Aksi</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-50">
                  {invoices.map(inv => (
                    <tr key={inv.id} className="hover:bg-slate-50/50">
                      <td className="px-6 py-3 font-mono text-xs text-indigo-600">{inv.invoiceNumber}</td>
                      <td className="px-6 py-3 font-bold">{inv.guest.name}</td>
                      <td className="px-6 py-3 text-right font-bold">Rp {formatCurrency(dashboardTab === 'with-tax' ? calculateTotal(inv) : calculateTotalNoTax(inv))}</td>
                      <td className="px-6 py-3"><span className="px-2 py-0.5 rounded-full text-[9px] font-bold uppercase bg-slate-100">{inv.status}</span></td>
                      <td className="px-6 py-3 text-right">
                        <button onClick={() => { setCurrentInvoice(inv); setViewMode('view'); }} className="text-indigo-600 font-bold text-xs hover:underline">View</button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}

        {viewMode === 'create' && currentInvoice && (
          <div className="flex-1 flex overflow-hidden p-4 gap-4 max-w-[1600px] w-full mx-auto">
            {/* Left Panel: Inputs */}
            <div className="flex-1 flex flex-col gap-4 overflow-hidden">
              {/* Guest & Stay - Very Compact */}
              <div className="bg-white border border-slate-200 rounded-2xl p-4 shrink-0 shadow-sm grid grid-cols-12 gap-4">
                <div className="col-span-4">
                  <label className="text-[9px] font-bold text-slate-400 uppercase mb-1 block">Nama Tamu</label>
                  <input type="text" className="w-full px-3 py-1.5 border border-slate-200 rounded-lg text-sm font-bold uppercase" value={currentInvoice.guest.name} onChange={e => setCurrentInvoice({...currentInvoice, guest: {...currentInvoice.guest, name: e.target.value.toUpperCase()}})} />
                </div>
                <div className="col-span-3">
                  <label className="text-[9px] font-bold text-slate-400 uppercase mb-1 block">Email</label>
                  <input type="email" className="w-full px-3 py-1.5 border border-slate-200 rounded-lg text-sm" value={currentInvoice.guest.email} onChange={e => setCurrentInvoice({...currentInvoice, guest: {...currentInvoice.guest, email: e.target.value}})} />
                </div>
                <div className="col-span-2">
                  <label className="text-[9px] font-bold text-slate-400 uppercase mb-1 block">Tipe Kamar</label>
                  <select className="w-full px-3 py-1.5 border border-slate-200 rounded-lg text-sm bg-white" value={currentInvoice.stay.roomType} onChange={e => setCurrentInvoice({...currentInvoice, stay: {...currentInvoice.stay, roomType: e.target.value}})}>
                    {ROOM_TYPES.map(t => <option key={t} value={t}>{t}</option>)}
                  </select>
                </div>
                <div className="col-span-1">
                  <label className="text-[9px] font-bold text-slate-400 uppercase mb-1 block">No RM</label>
                  <input type="text" className="w-full px-2 py-1.5 border border-slate-200 rounded-lg text-sm text-center font-bold" value={currentInvoice.stay.roomNumber} onChange={e => setCurrentInvoice({...currentInvoice, stay: {...currentInvoice.stay, roomNumber: e.target.value}})} />
                </div>
                <div className="col-span-2">
                  <label className="text-[9px] font-bold text-slate-400 uppercase mb-1 block">Check-in</label>
                  <input type="date" className="w-full px-2 py-1.5 border border-slate-200 rounded-lg text-xs" value={currentInvoice.stay.checkIn} onChange={e => setCurrentInvoice({...currentInvoice, stay: {...currentInvoice.stay, checkIn: e.target.value}})} />
                </div>
              </div>

              {/* Service List - Scrollable */}
              <div className="bg-white border border-slate-200 rounded-2xl flex-1 flex flex-col overflow-hidden shadow-sm">
                <div className="px-4 py-2 border-b border-slate-100 flex justify-between items-center bg-slate-50/50">
                  <h3 className="text-[10px] font-bold text-slate-500 uppercase">Daftar Layanan</h3>
                  <button onClick={() => { const id = Math.random().toString(36).substr(2,9); setCurrentInvoice({...currentInvoice, items: [...currentInvoice.items, {id, description:'', quantity:1, nights:1, unitPrice:0, total:0}]}) }} className="text-[10px] font-bold text-indigo-600 hover:bg-indigo-50 px-3 py-1 rounded-lg">+ Tambah</button>
                </div>
                <div className="flex-1 overflow-y-auto p-4 custom-scrollbar">
                  {currentInvoice.items.map(item => <InvoiceItemRow key={item.id} item={item} onUpdate={handleUpdateItem} onDelete={id => setCurrentInvoice({...currentInvoice, items: currentInvoice.items.filter(i => i.id !== id)})} />)}
                </div>
              </div>

              {/* Payments List - Scrollable */}
              <div className="bg-white border border-slate-200 rounded-2xl h-40 flex flex-col overflow-hidden shadow-sm">
                <div className="px-4 py-2 border-b border-slate-100 flex justify-between items-center bg-slate-50/50">
                  <h3 className="text-[10px] font-bold text-slate-500 uppercase">Riwayat Bayar</h3>
                  <button onClick={() => { const id = Math.random().toString(36).substr(2,9); setCurrentInvoice({...currentInvoice, payments: [...currentInvoice.payments, {id, date: new Date().toISOString().split('T')[0], method: PAYMENT_METHODS[0], amount:0}]}) }} className="text-[10px] font-bold text-emerald-600 hover:bg-emerald-50 px-3 py-1 rounded-lg">+ Catat</button>
                </div>
                <div className="flex-1 overflow-y-auto p-4 custom-scrollbar">
                  {currentInvoice.payments.map(p => <PaymentRow key={p.id} payment={p} onUpdate={handleUpdatePayment} onDelete={id => setCurrentInvoice({...currentInvoice, payments: currentInvoice.payments.filter(pay => pay.id !== id)})} />)}
                </div>
              </div>
            </div>

            {/* Right Panel: Summary & Save */}
            <div className="w-80 flex flex-col gap-4">
              <div className="bg-slate-900 rounded-3xl p-6 text-white flex-1 flex flex-col justify-between shadow-xl">
                <div>
                  <h3 className="text-[10px] font-bold text-indigo-400 uppercase tracking-widest text-center mb-6">Ringkasan Billing</h3>
                  <div className="space-y-3">
                    <div className="flex justify-between text-xs text-slate-400"><span>Subtotal</span><span>Rp {formatCurrency(calculateSubtotal(currentInvoice))}</span></div>
                    <div className="flex justify-between text-xs text-slate-400">
                      <span>Diskon</span>
                      <input type="text" className="w-24 bg-white/10 text-right px-2 py-0.5 rounded text-white text-xs" value={formatCurrency(currentInvoice.discount)} onChange={e => setCurrentInvoice({...currentInvoice, discount: parseInt(e.target.value.replace(/\D/g,'')) || 0})} />
                    </div>
                    <div className="h-px bg-white/10 my-4"></div>
                    <div className="text-center">
                      <p className="text-[9px] font-bold text-indigo-400 uppercase mb-1">Total (Inc. Pajak 11%)</p>
                      <h4 className="text-2xl font-serif font-bold">Rp {formatCurrency(calculateTotal(currentInvoice))}</h4>
                    </div>
                    <div className="text-center mt-4">
                      <p className="text-[9px] font-bold text-rose-400 uppercase mb-1">Sisa Tagihan</p>
                      <h4 className="text-2xl font-serif font-bold text-rose-500">Rp {formatCurrency(calculateTotal(currentInvoice) - calculatePaid(currentInvoice))}</h4>
                    </div>
                  </div>
                </div>

                <div className="space-y-4">
                  <div className="grid grid-cols-3 gap-1">
                    {['draft', 'paid', 'cancelled'].map(s => (
                      <button key={s} onClick={() => setCurrentInvoice({...currentInvoice, status: s as any})} className={`py-1.5 rounded-lg text-[8px] font-bold uppercase ${currentInvoice.status === s ? 'bg-indigo-600' : 'bg-white/5 text-slate-500'}`}>{s}</button>
