                  <button onClick={handleSaveInvoice} disabled={isGeneratingNote} className="w-full bg-indigo-500 hover:bg-indigo-600 text-white py-3 rounded-2xl font-bold shadow-lg shadow-indigo-500/20 active:scale-95 disabled:opacity-50 transition-all">
                    {isGeneratingNote ? 'AI Processing...' : 'Finalize & Simpan'}
                  </button>
                  <button onClick={() => setViewMode('list')} className="w-full text-center text-slate-500 text-[10px] font-bold uppercase hover:text-white transition-colors">Batal / Kembali</button>
                </div>
              </div>
            </div>
          </div>
        )}

        {viewMode === 'view' && currentInvoice && (
          <div className="flex-1 flex flex-col overflow-hidden">
            <div className="p-4 bg-white border-b border-slate-200 flex justify-between items-center no-print">
              <button onClick={() => setViewMode('list')} className="text-slate-500 font-bold text-xs flex items-center gap-2">
                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M10 19l-7-7m0 0l7-7m-7 7h18" /></svg>
                DASHBOARD
              </button>
              <div className="flex gap-2">
                <button onClick={() => setViewMode('create')} className="px-4 py-2 border border-slate-200 rounded-xl text-xs font-bold">Edit</button>
                <button onClick={() => window.print()} className="bg-slate-900 text-white px-6 py-2 rounded-xl text-xs font-bold shadow-lg">Cetak Invoice</button>
              </div>
            </div>
            <div className="flex-1 overflow-y-auto p-8 bg-slate-100/50 print:bg-white print:p-0">
              <InvoicePreview invoice={currentInvoice} settings={settings} />
            </div>
          </div>
        )}

        {viewMode === 'settings' && (
          <div className="flex-1 overflow-y-auto p-6">
            <SettingsPage settings={settings} onSave={handleSaveSettings} />
          </div>
        )}
      </main>

      <footer className="h-10 border-t border-slate-200 bg-white shrink-0 flex items-center px-6 no-print">
        <p className="text-[10px] text-slate-400 font-medium uppercase tracking-widest">&copy; 2024 HotelFlow Invoicing — {settings.name}</p>
      </footer>
    </div>
  );
};

