                          onClick={handleAutoGenerateRemarks} 
                          disabled={isGeneratingNote}
                          className="text-[8px] font-bold text-indigo-400 hover:text-white uppercase transition-colors flex items-center gap-1 disabled:opacity-50"
                        >
                          <svg className={`w-2.5 h-2.5 ${isGeneratingNote ? 'animate-spin' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
                          AI Generate
                        </button>
                      </div>
