                invoice.status === 'cancelled' ? 'bg-rose-100 text-rose-700' : 'bg-amber-100 text-amber-700'
              }`}>
                {invoice.status}
              </span>
            </div>

            <div className="col-span-2 border-t border-slate-200/50 my-0.5"></div>

            <span className="text-slate-400">Room No:</span>
            <span className="text-slate-800 font-bold text-right">{invoice.stay.roomNumber}</span>

            <span className="text-slate-400">Arrival :</span>
            <span className="text-slate-800 font-medium text-right">{formatIndonesianDate(invoice.stay.checkIn)}</span>

            <span className="text-slate-400">Departure :</span>
            <span className="text-slate-800 font-medium text-right">{formatIndonesianDate(invoice.stay.checkOut)}</span>
          </div>
        </div>
      </div>

      {/* Items Table */}
      <div className="overflow-hidden rounded-lg border border-slate-200 mb-4 shadow-sm bg-white">
        <table className="w-full">
          <thead>
            <tr className="bg-slate-800">
              <th className="py-2 px-6 text-left text-[8px] font-bold uppercase tracking-wider text-white">Description</th>
              <th className="py-2 px-4 text-center text-[8px] font-bold uppercase tracking-wider text-white">Qty</th>
              <th className="py-2 px-4 text-center text-[8px] font-bold uppercase tracking-wider text-white">Nights</th>
              <th className="py-2 px-6 text-right text-[8px] font-bold uppercase tracking-wider text-white">Unit Price</th>
              <th className="py-2 px-6 text-right text-[8px] font-bold uppercase tracking-wider text-white">Total Amount</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {invoice.items.map((item) => (
              <tr key={item.id} className="hover:bg-slate-50 transition-colors">
                <td className="py-2 px-6 text-slate-700 font-medium text-[11px]">{item.description}</td>
                <td className="py-2 px-4 text-center text-slate-500 text-[11px]">{item.quantity}</td>
                <td className="py-2 px-4 text-center text-slate-500 text-[11px]">{item.nights}</td>
                <td className="py-2 px-6 text-right text-slate-500 text-[11px]">Rp {formatCurrency(item.unitPrice)}</td>
                <td className="py-2 px-6 text-right text-slate-900 font-bold text-[11px]">Rp {formatCurrency(item.quantity * item.nights * item.unitPrice)}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* Payments History - Compact */}
      {invoice.payments.length > 0 && (
        <div className="mb-4 px-4 py-2 bg-slate-50/30 rounded-lg border border-slate-100">
          <h3 className="text-[8px] font-bold uppercase tracking-widest text-slate-400 mb-1 border-b border-slate-200 pb-0.5">Billing Activity</h3>
          <table className="w-full">
            <tbody className="divide-y divide-slate-100">
              {invoice.payments.map((p) => (
                <tr key={p.id}>
                  <td className="py-1 text-[9px] text-slate-500">{formatIndonesianDate(p.date)}</td>
                  <td className="py-1 text-[9px] font-bold text-slate-600 uppercase">{p.method}</td>
                  <td className="py-1 text-[10px] text-emerald-600 text-right font-bold"> - Rp {formatCurrency(p.amount)}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      {/* Summary Section */}
      <div className="flex justify-between items-start pt-4 border-t border-slate-200 gap-6">
        <div className="flex-1">
          {/* Section Remarks hanya tampil jika ada isinya */}
          {invoice.aiGreeting && (
            <div className="bg-white p-4 rounded-xl border border-slate-100 shadow-sm mb-4">
              <div className="flex items-center gap-2 mb-1.5">
                <div className="w-1.5 h-1.5 rounded-full bg-indigo-500"></div>
                <span className="text-[8px] font-bold text-slate-400 uppercase tracking-widest">Remarks</span>
              </div>
              <p className="text-slate-600 italic text-[10px] leading-relaxed font-medium">"{invoice.aiGreeting}"</p>
            </div>
          )}

          <div className="bg-slate-50/30 p-4 rounded-xl border border-slate-50">
            <p className="text-[7px] font-bold text-slate-400 uppercase tracking-widest mb-0.5">Payment Instructions:</p>
            <p className="text-slate-800 font-bold text-[9px] uppercase leading-tight">{hotel.name}</p>
            <p className="text-indigo-600 font-mono text-[10px] font-bold tracking-tight">BANK MANDIRI : 1770021861510</p>
          </div>
        </div>
        <div className="w-[200px] shrink-0">
          <div className="space-y-1.5 bg-slate-50 p-4 rounded-xl border border-slate-100 shadow-inner">
            <div className="flex justify-between text-slate-500 text-[9px] font-bold uppercase">
              <span>Subtotal:</span>
              <span>Rp {formatCurrency(subtotal)}</span>
            </div>
            {invoice.discount > 0 && (
              <div className="flex justify-between text-rose-500 text-[9px] font-bold uppercase">
                <span>Discount:</span>
                <span>- Rp {formatCurrency(invoice.discount)}</span>
              </div>
            )}
            <div className="flex justify-between text-emerald-600 text-[9px] font-bold uppercase">
              <span>Paid/Deposit:</span>
              <span>- Rp {formatCurrency(totalPaid)}</span>
            </div>
            <div className="h-px bg-slate-200 my-1.5"></div>
            <div className="flex flex-col items-end">
              <span className="text-[8px] font-bold text-slate-400 uppercase tracking-widest mb-0.5">Balance Due:</span>
              <span className="text-lg font-serif font-bold text-slate-900">Rp {formatCurrency(balanceDue)}</span>
            </div>
          </div>
        </div>
      </div>

      {/* Signature Section */}
      <div className="mt-10 grid grid-cols-2 gap-12 px-6 relative">
        <div className="text-center">
          <p className="text-[8px] font-bold text-slate-400 uppercase tracking-widest mb-16">Guest Signature</p>
          <div className="border-b border-slate-800 w-36 mx-auto"></div>
          <p className="text-[9px] text-slate-800 mt-1 font-bold uppercase">{invoice.guest.name || '________________'}</p>
        </div>
        <div className="text-center relative">
          <p className="text-[8px] font-bold text-slate-400 uppercase tracking-widest mb-16">Receptionist / Cashier</p>

          {/* DIGITAL SIGNATURE AND STAMP */}
          <div className="absolute top-[40%] left-1/2 -translate-x-1/2 -translate-y-1/2 w-full h-full pointer-events-none flex items-center justify-center overflow-visible">
            {hotel.signature && (
               <img src={hotel.signature} alt="Sign" className="absolute w-28 object-contain opacity-95 z-10 translate-y-2" />
            )}
            {hotel.stamp && (
               <img src={hotel.stamp} alt="Stamp" className="absolute w-28 object-contain opacity-70 rotate-[-15deg] -translate-x-6 -translate-y-2" />
            )}
          </div>

          <div className="border-b border-slate-800 w-36 mx-auto"></div>
          <p className="text-[9px] text-slate-800 mt-1 font-bold uppercase">{invoice.cashierName || '________________'}</p>
        </div>
      </div>

      {/* Footer Section */}
      <div className="mt-auto pt-6 text-center border-t border-slate-50">
          <p className="text-slate-400 text-[8px] uppercase font-bold tracking-[0.2em] mb-1">Issue Date: {formatIndonesianDate(invoice.date)}</p>
          <p className="text-slate-300 text-[7px] uppercase tracking-[0.1em]">Thank you for choosing {hotel.name} as your accommodation partner</p>
      </div>
    </div>
  );
};

export interface HotelSettings {
  name: string;
  address: string;
  phone: string;
  email: string;
  website: string;
  logo: string;
  signature?: string; // Base64 string for signature
  stamp?: string;     // Base64 string for hotel stamp
  defaultTaxRate: number;
  googleSheetUrl?: string; // URL dari Google Apps Script Web App
}

export interface InvoiceItem {
  id: string;
  description: string;
  quantity: number;
  nights: number;
  unitPrice: number;
  total: number;
}

export interface Payment {
  id: string;
  date: string;
  method: string;
  amount: number;
}

export interface GuestInfo {
  name: string;
  email: string;
  phone: string;
  address: string;
}

export interface StayDetails {
  roomNumber: string;
  roomType: string;
  checkIn: string;
  checkOut: string;
  guestsCount: number;
}

export interface Invoice {
  id: string;
  invoiceNumber: string;
  date: string;
  guest: GuestInfo;
  stay: StayDetails;
  items: InvoiceItem[];
  payments: Payment[];
  taxRate: number;
  discount: number;
  status: 'draft' | 'paid' | 'cancelled';
  notes: string;
  remarks?: string;
  hotelSnap?: HotelSettings;
  cashierName?: string;
}

export type ViewMode = 'list' | 'create' | 'view' | 'settings';

import React, { useState, useEffect, useCallback } from 'react';
import { Invoice, ViewMode, InvoiceItem, Payment, HotelSettings } from './types';
import { InvoicePreview } from './components/InvoicePreview';
import { InvoiceItemRow } from './components/InvoiceItemRow';
import { PaymentRow } from './components/PaymentRow';
import { SettingsPage } from './components/SettingsPage';
import { ROOM_TYPES, PAYMENT_METHODS, HOTEL_INFO, TAX_RATE } from './constants';

declare var html2pdf: any;

const INITIAL_GUEST = { name: '', email: '', phone: '', address: '' };
const INITIAL_STAY = { roomNumber: '', roomType: ROOM_TYPES[0], checkIn: '', checkOut: '', guestsCount: 1 };

const App: React.FC = () => {
  const [viewMode, setViewMode] = useState<ViewMode>('list');
  const [invoices, setInvoices] = useState<Invoice[]>([]);
  const [currentInvoice, setCurrentInvoice] = useState<Invoice | null>(null);
  const [syncStatus, setSyncStatus] = useState<'idle' | 'syncing' | 'success' | 'error'>('idle');

  // Initialize settings from localStorage or fallback to HOTEL_INFO
  const [settings, setSettings] = useState<HotelSettings>(() => {
    const saved = localStorage.getItem('hotelflow_settings');
    if (saved) return JSON.parse(saved);
    return {
      ...HOTEL_INFO,
      defaultTaxRate: TAX_RATE,
      googleSheetUrl: HOTEL_INFO.googleSheetUrl
    };
  });

  // Initial load for invoices
  useEffect(() => {
    const savedInvoices = localStorage.getItem('hotelflow_invoices');
    if (savedInvoices) setInvoices(JSON.parse(savedInvoices));
  }, []);

  // Automatic persistence for invoices
  useEffect(() => {
    localStorage.setItem('hotelflow_invoices', JSON.stringify(invoices));
  }, [invoices]);

  // Automatic persistence for settings
  useEffect(() => {
    localStorage.setItem('hotelflow_settings', JSON.stringify(settings));
  }, [settings]);

  const fetchFromCloud = useCallback(async () => {
    if (!settings.googleSheetUrl || !settings.googleSheetUrl.includes('script.google.com')) return;

    setSyncStatus('syncing');
    try {
      const url = new URL(settings.googleSheetUrl);
      url.searchParams.set('type', 'fetch');
      url.searchParams.set('cacheBust', Date.now().toString());

      const response = await fetch(url.toString(), {
        method: 'GET',
        mode: 'cors',
        headers: { 'Accept': 'application/json' }
      });

      if (!response.ok) throw new Error('Network response was not ok');

      const cloudData = await response.json();
      if (Array.isArray(cloudData)) {
        setInvoices(prev => {
          const combined = [...cloudData];
          prev.forEach(localInv => {
            if (!combined.find(c => c.invoiceNumber === localInv.invoiceNumber)) {
              combined.push(localInv);
            }
          });
          return combined.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
        });
        setSyncStatus('success');
      }
    } catch (error) {
      console.error("Cloud Fetch Error:", error);
      setSyncStatus('error');
    } finally {
      setTimeout(() => setSyncStatus('idle'), 3000);
    }
  }, [settings.googleSheetUrl]);

  useEffect(() => {
    if (viewMode === 'list') {
      fetchFromCloud();
    }
  }, [viewMode, fetchFromCloud]);

  const syncToCloud = useCallback(async (type: 'settings' | 'invoice', payload: any) => {
    if (!settings.googleSheetUrl || !settings.googleSheetUrl.includes('script.google.com')) return;

    setSyncStatus('syncing');
    try {
      await fetch(settings.googleSheetUrl, {
        method: 'POST',
        mode: 'no-cors',
        headers: { 'Content-Type': 'text/plain' },
        body: JSON.stringify({ type, payload })
      });

      setSyncStatus('success');
      setTimeout(() => setSyncStatus('idle'), 3000);
    } catch (error) {
      console.error("Cloud Sync Error:", error);
      setSyncStatus('error');
    }
  }, [settings.googleSheetUrl]);

  const handleSaveSettings = (newSettings: HotelSettings) => {
    setSettings(newSettings);
    syncToCloud('settings', newSettings);
  };

  const calculateSubtotal = (inv: Invoice) => inv.items.reduce((sum, item) => sum + (item.quantity * item.nights * item.unitPrice), 0);
  const calculateTotal = (inv: Invoice) => calculateSubtotal(inv) - inv.discount;
  const formatCurrency = (val: number) => val.toLocaleString('id-ID');

  const handleSaveInvoice = async () => {
    if (!currentInvoice) return;

    const isDuplicateNumber = invoices.some(inv => 
      inv.invoiceNumber === currentInvoice.invoiceNumber && inv.id !== currentInvoice.id
    );

    if (isDuplicateNumber) {
      alert(`Peringatan: Nomor Invoice ${currentInvoice.invoiceNumber} sudah digunakan oleh transaksi lain.`);
      return;
    }

    const finalizedInvoice = { ...currentInvoice, hotelSnap: settings };

    setInvoices(prev => {
      const exists = prev.find(i => i.id === finalizedInvoice.id);
      return exists ? prev.map(i => i.id === finalizedInvoice.id ? finalizedInvoice : i) : [finalizedInvoice, ...prev];
    });

    setCurrentInvoice(finalizedInvoice);
    setViewMode('view');
    syncToCloud('invoice', finalizedInvoice);
  };

  const downloadPDF = () => {
    if (!currentInvoice) return;
    const element = document.getElementById('invoice-content');
    if (!element) return;

    const opt = {
      margin: 0,
      filename: `Invoice_${currentInvoice.invoiceNumber}_${currentInvoice.guest.name.replace(/\s+/g, '_')}.pdf`,
      image: { type: 'jpeg', quality: 0.98 },
      html2canvas: { 
        scale: 3, 
        useCORS: true,
        letterRendering: true,
        backgroundColor: '#FFFFFF'
      },
      jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' }
    };
    html2pdf().set(opt).from(element).save();
  };

  const handleUpdateItem = (id: string, updates: Partial<InvoiceItem>) => {
    if (!currentInvoice) return;
    setCurrentInvoice({
      ...currentInvoice,
      items: currentInvoice.items.map(item => item.id === id ? { ...item, ...updates } : item)
    });
  };

  const handleUpdatePayment = (id: string, updates: Partial<Payment>) => {
    if (!currentInvoice) return;
    setCurrentInvoice({
      ...currentInvoice,
      payments: currentInvoice.payments.map(p => p.id === id ? { ...p, ...updates } : p)
    });
  };

  const createNewInvoice = () => {
    const id = Math.random().toString(36).substr(2, 9);
    const lastCashier = invoices.length > 0 ? invoices[0].cashierName : '';
    const currentYear = new Date().getFullYear();
    const prefix = `INV-${currentYear}-`;

    const sequenceNumbers = invoices
      .filter(inv => inv.invoiceNumber.startsWith(prefix))
      .map(inv => {
        const parts = inv.invoiceNumber.split('-');
        const sequencePart = parts[parts.length - 1];
        return parseInt(sequencePart, 10);
      })
      .filter(num => !isNaN(num));

    const maxSequence = sequenceNumbers.length > 0 ? Math.max(...sequenceNumbers) : 0;
    const nextSequence = maxSequence + 1;
    const newInvoiceNumber = `${prefix}${nextSequence.toString().padStart(4, '0')}`;

    setCurrentInvoice({
      id,
      invoiceNumber: newInvoiceNumber,
      date: new Date().toISOString().split('T')[0],
      guest: { ...INITIAL_GUEST },
      stay: { ...INITIAL_STAY },
      items: [{ id: '1', description: '', quantity: 1, nights: 1, unitPrice: 0, total: 0 }],
      payments: [],
      taxRate: 0, 
      discount: 0,
      status: 'draft',
      notes: '',
      remarks: '', 
      hotelSnap: settings,
      cashierName: lastCashier || ''
    });
    setViewMode('create');
  };

  return (
    <div className="h-screen bg-slate-50 flex flex-col overflow-hidden">
      <header className="bg-white border-b border-slate-200 h-14 shrink-0 flex items-center z-50 no-print">
        <div className="max-w-[1600px] w-full mx-auto px-6 flex justify-between items-center">
          <div className="flex items-center gap-6">
            <div className="flex items-center gap-2 cursor-pointer" onClick={() => setViewMode('list')}>
              <div className="bg-indigo-600 p-1.5 rounded-lg">
                <svg className="w-5 h-5 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 21V5a2 2 0 00-2-2H7a2 2 0 00-2 2v16m14 0h2m-2 0h-5m-9 0H3m2 0h5M9 7h1m-1 4h1m4-4h1m-1 4h1m-5 10v-5a1 1 0 011-1h2a1 1 0 011 1v5m-4 0h4" /></svg>
              </div>
              <h1 className="text-lg font-bold text-slate-900">HotelFlow</h1>
            </div>
            <nav className="flex items-center gap-1">
              <button onClick={() => setViewMode('list')} className={`px-4 py-1.5 rounded-lg text-xs font-bold ${viewMode === 'list' ? 'bg-slate-900 text-white' : 'text-slate-500 hover:bg-slate-100'}`}>Beranda</button>
              <button onClick={() => setViewMode('settings')} className={`px-4 py-1.5 rounded-lg text-xs font-bold ${viewMode === 'settings' ? 'bg-slate-900 text-white' : 'text-slate-500 hover:bg-slate-100'}`}>Settings</button>
            </nav>
          </div>
          <div className="flex items-center gap-4">
            {syncStatus !== 'idle' && (
              <div className={`flex items-center gap-2 text-[10px] font-bold uppercase tracking-widest ${syncStatus === 'error' ? 'text-rose-500' : 'text-indigo-500'}`}>
                {syncStatus === 'syncing' ? 'Syncing...' : syncStatus === 'success' ? 'Cloud Synced' : 'Sync Failed'}
              </div>
            )}
            <button onClick={createNewInvoice} className="bg-indigo-600 text-white px-5 py-2 rounded-xl text-sm font-bold shadow-lg hover:bg-indigo-700 active:scale-95 transition-all flex items-center gap-2">
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 4v16m8-8H4" /></svg>
              Buat Invoice
            </button>
          </div>
        </div>
      </header>

      <main className="flex-1 overflow-hidden flex flex-col relative">
        {viewMode === 'list' && (
          <div className="flex-1 overflow-y-auto p-6 max-w-[1600px] w-full mx-auto animate-fade-in">
            <div className="flex justify-between items-end mb-6">
              <div className="flex items-center gap-3">
                <h2 className="text-2xl font-bold text-slate-900">Dashboard Tagihan</h2>
                <button onClick={fetchFromCloud} className="p-2 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-full transition-all">
                  <svg className={`w-4 h-4 ${syncStatus === 'syncing' ? 'animate-spin' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15" /></svg>
                </button>
              </div>
              <div className="bg-slate-200 px-4 py-1.5 rounded-xl flex shadow-inner text-[10px] font-bold text-slate-500 uppercase tracking-widest">
                {invoices.length} Transaksi Tersimpan
              </div>
            </div>

            <div className="bg-white border border-slate-200 rounded-3xl shadow-sm overflow-hidden">
              <table className="w-full text-left text-sm">
                <thead className="bg-slate-50 border-b border-slate-100">
                  <tr>
                    <th className="px-6 py-4 font-bold text-slate-400 text-[10px] uppercase">ID Invoice</th>
                    <th className="px-6 py-4 font-bold text-slate-400 text-[10px] uppercase">Nama Tamu</th>
                    <th className="px-6 py-4 font-bold text-slate-400 text-[10px] uppercase text-right">Total Bayar</th>
                    <th className="px-6 py-4 font-bold text-slate-400 text-[10px] uppercase">Status</th>
                    <th className="px-6 py-4 text-right">Aksi</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-50">
                  {invoices.length === 0 ? (
                    <tr><td colSpan={5} className="px-6 py-12 text-center text-slate-400 italic">Belum ada riwayat transaksi. Klik "Buat Invoice" untuk memulai.</td></tr>
                  ) : (
                    invoices.map(inv => (
                      <tr key={inv.id} className="hover:bg-slate-50/50 transition-colors">
                        <td className="px-6 py-3 font-mono text-xs text-indigo-600">{inv.invoiceNumber}</td>
                        <td className="px-6 py-3 font-bold">{inv.guest.name}</td>
                        <td className="px-6 py-3 text-right font-bold">Rp {formatCurrency(calculateTotal(inv))}</td>
                        <td className="px-6 py-3"><span className={`px-2 py-0.5 rounded-full text-[9px] font-bold uppercase ${inv.status === 'paid' ? 'bg-emerald-100 text-emerald-600' : 'bg-slate-100 text-slate-500'}`}>{inv.status}</span></td>
                        <td className="px-6 py-3 text-right">
                          <button onClick={() => { setCurrentInvoice(inv); setViewMode('view'); }} className="text-indigo-600 font-bold text-xs hover:underline">Lihat</button>
                        </td>
                      </tr>
                    ))
                  )}
                </tbody>
              </table>
            </div>
          </div>
        )}

        {viewMode === 'create' && currentInvoice && (
          <div className="flex-1 flex overflow-hidden p-4 gap-4 max-w-[1600px] w-full mx-auto animate-fade-in">
            <div className="flex-1 flex flex-col gap-4 overflow-hidden">
              <div className="flex gap-4 shrink-0">
                <div className="flex-1 bg-white border border-slate-200 rounded-2xl p-4 shadow-sm">
                  <h3 className="text-[10px] font-bold text-slate-400 uppercase mb-3 flex items-center gap-2">Identitas Tamu</h3>
                  <div className="grid grid-cols-2 gap-3">
                    <div className="col-span-2">
                      <label className="text-[9px] font-bold text-slate-400 uppercase mb-1 block">Nama Lengkap</label>
                      <input type="text" className="w-full px-3 py-1.5 border border-slate-200 rounded-lg text-sm font-bold uppercase" value={currentInvoice.guest.name} onChange={e => setCurrentInvoice({...currentInvoice, guest: {...currentInvoice.guest, name: e.target.value.toUpperCase()}})} />
                    </div>
                    <div>
                      <label className="text-[9px] font-bold text-slate-400 uppercase mb-1 block">Telepon / WA</label>
                      <input type="text" className="w-full px-3 py-1.5 border border-slate-200 rounded-lg text-sm" value={currentInvoice.guest.phone} onChange={e => setCurrentInvoice({...currentInvoice, guest: {...currentInvoice.guest, phone: e.target.value}})} />
                    </div>
                    <div>
                      <label className="text-[9px] font-bold text-slate-400 uppercase mb-1 block">Email</label>
                      <input type="email" className="w-full px-3 py-1.5 border border-slate-200 rounded-lg text-sm" value={currentInvoice.guest.email} onChange={e => setCurrentInvoice({...currentInvoice, guest: {...currentInvoice.guest, email: e.target.value}})} />
                    </div>
