import { createClient, SupabaseClient } from '@supabase/supabase-js';
import { Invoice, HotelSettings } from '../types';

let supabase: SupabaseClient | null = null;
// Track the current URL to avoid accessing protected property 'supabaseUrl' on SupabaseClient
let currentSupabaseUrl: string | null = null;

export const getSupabaseClient = (settings: HotelSettings) => {
  if (settings.supabaseUrl && settings.supabaseAnonKey) {
    // Fix: Accessing protected property 'supabaseUrl' on SupabaseClient is not allowed.
    // We compare with our tracked currentSupabaseUrl instead.
    if (!supabase || currentSupabaseUrl !== settings.supabaseUrl) {
      supabase = createClient(settings.supabaseUrl, settings.supabaseAnonKey);
      currentSupabaseUrl = settings.supabaseUrl;
    }
    return supabase;
  }
  return null;
};

export const fetchInvoicesFromSupabase = async (settings: HotelSettings): Promise<Invoice[]> => {
  const client = getSupabaseClient(settings);
  if (!client) return [];

  try {
    const { data, error } = await client
      .from('invoices')
      .select('data')
      .order('created_at', { ascending: false });

    if (error) throw error;
    return (data || []).map((row: any) => row.data as Invoice);
  } catch (err) {
    console.error('Supabase Fetch Error:', err);
    return [];
  }
};

export const upsertInvoiceToSupabase = async (invoice: Invoice, settings: HotelSettings): Promise<boolean> => {
  const client = getSupabaseClient(settings);
  if (!client) return false;

  try {
    const { error } = await client
      .from('invoices')
      .upsert({ 
        id: invoice.id, 
        invoice_number: invoice.invoiceNumber, 
        data: invoice,
        updated_at: new Date().toISOString()
      }, { onConflict: 'id' });

    if (error) throw error;
    return true;
  } catch (err) {
    console.error('Supabase Upsert Error:', err);
    return false;
  }
};

export const saveSettingsToSupabase = async (hotelSettings: HotelSettings): Promise<boolean> => {
  const client = getSupabaseClient(hotelSettings);
  if (!client) return false;

  try {
    const { error } = await client
      .from('settings')
      .upsert({ 
        id: 'hotel_profile', 
        data: hotelSettings,
        updated_at: new Date().toISOString()
      }, { onConflict: 'id' });

    if (error) throw error;
    return true;
  } catch (err) {
    console.error('Supabase Settings Save Error:', err);
    return false;
  }
};

import { GoogleGenAI } from "@google/genai";
import { Invoice } from "../types";

export const generatePersonalizedNote = async (invoice: Invoice): Promise<string> => {
  try {
    // Always initialize a new GoogleGenAI instance right before the call.
    // Use process.env.API_KEY directly as per guidelines.
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY as string });

    const prompt = `
      Act as a high-end luxury hotel concierge. 
      Generate a short, professional, and warm thank-you note for a guest stay.
      Guest Name: ${invoice.guest.name}
      Room Type: ${invoice.stay.roomType}
      Stay: From ${invoice.stay.checkIn} to ${invoice.stay.checkOut}
      Items billed include: ${invoice.items.map(i => i.description).join(', ')}

      The note should mention their specific room type and wish them a pleasant journey. 
      Keep it under 60 words. Language: Indonesian (Sopan/Formal).
    `;

    // Always query GenAI with both the model name and prompt in a single call.
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });

    // Use .text property (not a method) to extract output text.
    return response.text || "Terima kasih telah menginap bersama kami. Kami berharap dapat menyambut Anda kembali.";
  } catch (error) {
    console.error("Gemini Error:", error);
    return "Terima kasih telah menginap di Blue Orchid. Semoga perjalanan Anda menyenangkan.";
  }
};

import React, { useState, useEffect, useCallback } from 'react';
import { Invoice, ViewMode, InvoiceItem, Payment, HotelSettings } from './types';
import { InvoicePreview } from './components/InvoicePreview';
import { InvoiceItemRow } from './components/InvoiceItemRow';
import { PaymentRow } from './components/PaymentRow';
import { SettingsPage } from './components/SettingsPage';
import { ROOM_TYPES, GUEST_TYPES, PAYMENT_METHODS, HOTEL_INFO, TAX_RATE } from './constants';
import { fetchInvoicesFromSupabase, upsertInvoiceToSupabase, saveSettingsToSupabase } from './services/supabaseService';
import { generatePersonalizedNote } from './services/geminiService';

declare var html2pdf: any;

const INITIAL_GUEST = { name: '', email: '', phone: '', address: '' };
const INITIAL_STAY = { roomNumber: '', roomType: ROOM_TYPES[0], guestType: GUEST_TYPES[0], checkIn: '', checkOut: '', guestsCount: 1 };

const App: React.FC = () => {
  const [viewMode, setViewMode] = useState<ViewMode>('list');
  const [invoices, setInvoices] = useState<Invoice[]>([]);
  const [currentInvoice, setCurrentInvoice] = useState<Invoice | null>(null);
  const [syncStatus, setSyncStatus] = useState<'idle' | 'syncing' | 'success' | 'error'>('idle');
  const [isGeneratingNote, setIsGeneratingNote] = useState(false);

  const [settings, setSettings] = useState<HotelSettings>(() => {
    const saved = localStorage.getItem('hotelflow_settings');
    if (saved) {
      const parsed = JSON.parse(saved);
      // Merge with HOTEL_INFO to ensure new default credentials like Supabase keys are picked up
      return { ...HOTEL_INFO, ...parsed, defaultTaxRate: parsed.defaultTaxRate ?? TAX_RATE };
    }
    return {
      ...HOTEL_INFO,
      defaultTaxRate: TAX_RATE,
    };
  });

  useEffect(() => {
    const savedInvoices = localStorage.getItem('hotelflow_invoices');
    if (savedInvoices) setInvoices(JSON.parse(savedInvoices));
  }, []);

  useEffect(() => {
    localStorage.setItem('hotelflow_invoices', JSON.stringify(invoices));
  }, [invoices]);

  useEffect(() => {
    localStorage.setItem('hotelflow_settings', JSON.stringify(settings));
  }, [settings]);

  const syncFromSupabase = useCallback(async () => {
    if (!settings.supabaseUrl || !settings.supabaseAnonKey) return;

    setSyncStatus('syncing');
    try {
      const cloudInvoices = await fetchInvoicesFromSupabase(settings);
      setInvoices(prev => {
        const combined = [...cloudInvoices];
        prev.forEach(localInv => {
          const alreadyExists = combined.some(c => c.id === localInv.id);
          if (!alreadyExists) {
            combined.push(localInv);
          }
        });
        return combined.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
      });
      setSyncStatus('success');
    } catch (error) {
      console.error("Supabase Sync Error:", error);
      setSyncStatus('error');
    } finally {
      setTimeout(() => setSyncStatus('idle'), 3000);
    }
  }, [settings]);

  useEffect(() => {
    if (viewMode === 'list') {
      syncFromSupabase();
    }
  }, [viewMode, syncFromSupabase]);

  const handleSaveSettings = async (newSettings: HotelSettings) => {
    setSettings(newSettings);
    if (newSettings.supabaseUrl && newSettings.supabaseAnonKey) {
      setSyncStatus('syncing');
      const success = await saveSettingsToSupabase(newSettings);
      setSyncStatus(success ? 'success' : 'error');
      setTimeout(() => setSyncStatus('idle'), 3000);
    }
  };

  const handleGenerateAINote = async () => {
    if (!currentInvoice) return;
    setIsGeneratingNote(true);
    try {
      const note = await generatePersonalizedNote(currentInvoice);
      setCurrentInvoice({ ...currentInvoice, remarks: note });
    } catch (error) {
      console.error("AI Generation failed", error);
    } finally {
      setIsGeneratingNote(false);
    }
  };

  const calculateSubtotal = (inv: Invoice) => inv.items.reduce((sum, item) => sum + (item.quantity * item.nights * item.unitPrice), 0);
  const calculateTotal = (inv: Invoice) => calculateSubtotal(inv) - inv.discount;
  const formatCurrency = (val: number) => val.toLocaleString('id-ID');

  const handleSaveInvoice = async () => {
    if (!currentInvoice) return;

    const isDuplicateNumber = invoices.some(inv => 
      inv.invoiceNumber === currentInvoice.invoiceNumber && inv.id !== currentInvoice.id
    );

    if (isDuplicateNumber) {
      alert(`Peringatan: Nomor Invoice ${currentInvoice.invoiceNumber} sudah digunakan.`);
      return;
    }

    const finalizedInvoice = { ...currentInvoice, hotelSnap: settings };

    setInvoices(prev => {
      const index = prev.findIndex(i => i.id === finalizedInvoice.id);
      if (index !== -1) {
        const newList = [...prev];
        newList[index] = finalizedInvoice;
        return newList;
      } else {
        return [finalizedInvoice, ...prev];
      }
    });

    setCurrentInvoice(finalizedInvoice);
    setViewMode('view');

    if (settings.supabaseUrl && settings.supabaseAnonKey) {
      setSyncStatus('syncing');
      const success = await upsertInvoiceToSupabase(finalizedInvoice, settings);
      setSyncStatus(success ? 'success' : 'error');
      setTimeout(() => setSyncStatus('idle'), 3000);
    }
  };

  const downloadPDF = () => {
    if (!currentInvoice) return;
    const element = document.getElementById('invoice-content');
    if (!element) return;

    const opt = {
      margin: 0,
      filename: `Invoice_${currentInvoice.invoiceNumber}_${currentInvoice.guest.name.replace(/\s+/g, '_')}.pdf`,
      image: { type: 'jpeg', quality: 0.98 },
      html2canvas: { 
        scale: 3, 
        useCORS: true,
        letterRendering: true,
        backgroundColor: '#FFFFFF'
      },
      jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' },
      pagebreak: { mode: ['avoid-all', 'css', 'legacy'] }
    };
    html2pdf().set(opt).from(element).save();
  };

  const handleUpdateItem = (id: string, updates: Partial<InvoiceItem>) => {
    if (!currentInvoice) return;
    setCurrentInvoice({
      ...currentInvoice,
      items: currentInvoice.items.map(item => item.id === id ? { ...item, ...updates } : item)
    });
  };

  const handleUpdatePayment = (id: string, updates: Partial<Payment>) => {
    if (!currentInvoice) return;
    setCurrentInvoice({
      ...currentInvoice,
      payments: currentInvoice.payments.map(p => p.id === id ? { ...p, ...updates } : p)
    });
  };

  const createNewInvoice = () => {
    const id = Math.random().toString(36).substr(2, 9);
    const lastCashier = invoices.length > 0 ? invoices[0].cashierName : '';
    const currentYear = new Date().getFullYear();
    const prefix = `INV-${currentYear}-`;

    const sequenceNumbers = invoices
      .filter(inv => inv.invoiceNumber.startsWith(prefix))
      .map(inv => {
        const parts = inv.invoiceNumber.split('-');
        const sequencePart = parts[parts.length - 1];
        return parseInt(sequencePart, 10);
      })
      .filter(num => !isNaN(num));

    const maxSequence = sequenceNumbers.length > 0 ? Math.max(...sequenceNumbers) : 0;
    const nextSequence = maxSequence + 1;
    const newInvoiceNumber = `${prefix}${nextSequence.toString().padStart(4, '0')}`;

    setCurrentInvoice({
      id,
      invoiceNumber: newInvoiceNumber,
      date: new Date().toISOString().split('T')[0],
      guest: { ...INITIAL_GUEST },
      stay: { ...INITIAL_STAY },
      items: [{ id: '1', description: '', quantity: 1, nights: 1, unitPrice: 0, total: 0 }],
      payments: [],
      taxRate: 0, 
      discount: 0,
      status: 'draft',
      notes: '',
      remarks: '', 
      hotelSnap: settings,
      cashierName: lastCashier || ''
    });
    setViewMode('create');
  };

