            <div className="w-full lg:w-80 flex flex-col gap-4 shrink-0">
              <div className="bg-slate-900 rounded-2xl lg:rounded-3xl p-6 text-white flex-1 flex flex-col justify-between shadow-xl min-h-[400px]">
