    { label: 'Tamu', icon: '👤' },
    { label: 'Menginap', icon: '🏨' },
    { label: 'Layanan', icon: '🍽️' },
    { label: 'Bayar', icon: '💳' },
    { label: 'Final', icon: '✅' }
