import { createClient, SupabaseClient, User, Session } from '@supabase/supabase-js';
import { Invoice, HotelSettings, UserProfile, UserRole } from '../types';
import { HOTEL_INFO } from '../constants';

let activeUrl = HOTEL_INFO.supabaseUrl;
let supabase: SupabaseClient = createClient(activeUrl, HOTEL_INFO.supabaseAnonKey);

export const getSupabaseClient = (settings?: HotelSettings) => {
  if (settings?.supabaseUrl && settings?.supabaseAnonKey) {
    if (activeUrl !== settings.supabaseUrl) {
      activeUrl = settings.supabaseUrl;
      supabase = createClient(activeUrl, settings.supabaseAnonKey);
    }
  }
  return supabase;
};

// --- Auth & Profile Functions ---
export const signIn = async (email: string, pass: string) => {
  return await supabase.auth.signInWithPassword({ email, password: pass });
};

export const signUpNewUser = async (email: string, pass: string, role: UserRole) => {
  // Note: SignUp logs the user in automatically on standard Supabase config.
  // In a real management system, this would be an admin edge function.
  const { data, error } = await supabase.auth.signUp({ 
    email, 
    password: pass,
    options: {
      data: { role } // Store in metadata
    }
  });

  if (error) return { error };

  // Create profile entry
  if (data.user) {
    await upsertProfile({
      id: data.user.id,
      email: email,
      role: role,
      updated_at: new Date().toISOString()
    });
  }

  return { data };
};

export const signOut = async () => {
  return await supabase.auth.signOut();
};

export const onAuthStateChange = (callback: (session: Session | null) => void) => {
  return supabase.auth.onAuthStateChange((_event, session) => {
    callback(session);
  });
};

export const fetchProfiles = async (): Promise<UserProfile[]> => {
  try {
    const { data, error } = await supabase
      .from('profiles')
      .select('*')
      .order('updated_at', { ascending: false });

    if (error) throw error;
    return data || [];
  } catch (err) {
    console.error("Fetch Profiles Error:", err);
    return [];
  }
};

export const upsertProfile = async (profile: UserProfile) => {
  return await supabase
    .from('profiles')
    .upsert(profile, { onConflict: 'id' });
};

export const getCurrentUserProfile = async (userId: string): Promise<UserProfile | null> => {
  const { data, error } = await supabase
    .from('profiles')
    .select('*')
    .eq('id', userId)
    .single();

  if (error) return null;
  return data;
};

// --- Storage & Data Functions ---
export const uploadAsset = async (file: File, settings: HotelSettings, folder: string): Promise<string | null> => {
  const client = getSupabaseClient(settings);
  const fileExt = file.name.split('.').pop();
  const fileName = `${folder}_${Math.random().toString(36).substring(2)}_${Date.now()}.${fileExt}`;

  try {
    const { error: uploadError } = await client.storage
      .from('hotel-assets')
      .upload(fileName, file);

    if (uploadError) throw uploadError;

    const { data } = client.storage
      .from('hotel-assets')
      .getPublicUrl(fileName);

    return data.publicUrl;
  } catch (err) {
    console.error('Storage Upload Error:', err);
    return null;
  }
};

export const fetchSettingsFromSupabase = async (settings: HotelSettings): Promise<HotelSettings | null> => {
  const client = getSupabaseClient(settings);
  try {
    const { data, error } = await client
      .from('settings')
      .select('data')
      .eq('id', 'hotel_profile')
      .single();

    if (error && error.code !== 'PGRST116') throw error;
    return data ? (data.data as HotelSettings) : null;
  } catch (err) {
    return null;
  }
};

export const fetchInvoicesFromSupabase = async (settings: HotelSettings): Promise<Invoice[]> => {
  const client = getSupabaseClient(settings);
  try {
    const { data, error } = await client
      .from('invoices')
      .select('data')
      .order('updated_at', { ascending: false });

    if (error) throw error;
    return (data || []).map((row: any) => row.data as Invoice);
  } catch (err) {
    return [];
  }
};

export const upsertInvoiceToSupabase = async (invoice: Invoice, settings: HotelSettings): Promise<boolean> => {
  const client = getSupabaseClient(settings);
  try {
    const { error } = await client
      .from('invoices')
      .upsert({ 
        id: invoice.id, 
        invoice_number: invoice.invoiceNumber, 
        data: invoice,
        updated_at: new Date().toISOString()
      }, { onConflict: 'id' });

    return !error;
  } catch (err) {
    return false;
  }
};

export const saveSettingsToSupabase = async (hotelSettings: HotelSettings): Promise<boolean> => {
  const client = getSupabaseClient(hotelSettings);
  try {
    const { error } = await client
      .from('settings')
      .upsert({ 
        id: 'hotel_profile', 
        data: hotelSettings,
        updated_at: new Date().toISOString()
      }, { onConflict: 'id' });

    return !error;
  } catch (err) {
    return false;
  }
};

import React, { useState, useEffect } from 'react';
import { HotelSettings, UserProfile, UserRole } from '../types';
import { uploadAsset, fetchProfiles, signUpNewUser, upsertProfile } from '../services/supabaseService';

interface Props {
  settings: HotelSettings;
  onSave: (settings: HotelSettings) => void;
  currentUserRole?: UserRole;
}

export const SettingsPage: React.FC<Props> = ({ settings, onSave, currentUserRole }) => {
  const [activeTab, setActiveTab] = useState<'profile' | 'accounts'>('profile');
  const [formData, setFormData] = React.useState<HotelSettings>(settings);
  const [isUploading, setIsUploading] = useState<string | null>(null);

  // Account Management States
  const [profiles, setProfiles] = useState<UserProfile[]>([]);
  const [newUser, setNewUser] = useState({ email: '', password: '', role: 'receptionist' as UserRole });
  const [isCreatingUser, setIsCreatingUser] = useState(false);

  useEffect(() => {
    if (activeTab === 'accounts' && currentUserRole === 'admin') {
      loadProfiles();
    }
  }, [activeTab, currentUserRole]);

  const loadProfiles = async () => {
    const data = await fetchProfiles();
    setProfiles(data);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSave(formData);
    alert('Pengaturan berhasil diperbarui!');
  };

  const handleCreateUser = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newUser.email || !newUser.password) return;
    setIsCreatingUser(true);
    try {
      const { error } = await signUpNewUser(newUser.email, newUser.password, newUser.role);
      if (error) throw error;
      alert('Akun baru berhasil didaftarkan!');
      setNewUser({ email: '', password: '', role: 'receptionist' });
      loadProfiles();
    } catch (err: any) {
      alert('Error: ' + err.message);
    } finally {
      setIsCreatingUser(false);
    }
  };

  const handleChangeRole = async (userId: string, newRole: UserRole) => {
    if (!confirm(`Ubah role pengguna ini menjadi ${newRole}?`)) return;
    const profile = profiles.find(p => p.id === userId);
    if (profile) {
      await upsertProfile({ ...profile, role: newRole });
      loadProfiles();
    }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>, field: 'signature' | 'stamp' | 'logo') => {
    const file = e.target.files?.[0];
    if (file) {
      if (!formData.supabaseUrl || !formData.supabaseAnonKey) {
        alert('Mohon lengkapi konfigurasi Supabase terlebih dahulu.');
        return;
      }
      setIsUploading(field);
      try {
        const publicUrl = await uploadAsset(file, formData, field);
        if (publicUrl) {
          if (field === 'logo') {
            setFormData({ ...formData, logo: publicUrl, stamp: publicUrl });
          } else {
            setFormData({ ...formData, [field]: publicUrl });
          }
        }
      } catch (error) {
        console.error("Upload error:", error);
      } finally {
        setIsUploading(null);
      }
    }
  };

  return (
    <div className="max-w-4xl mx-auto animate-in fade-in slide-in-from-bottom-4 duration-500 pb-12">
      <div className="bg-white rounded-3xl shadow-xl border border-slate-200 overflow-hidden mb-8">
        <div className="flex border-b border-slate-100">
          <button 
            onClick={() => setActiveTab('profile')}
            className={`flex-1 py-5 text-sm font-bold uppercase tracking-wider transition-all ${activeTab === 'profile' ? 'bg-white text-indigo-600 border-b-2 border-indigo-600' : 'bg-slate-50 text-slate-400 hover:text-slate-600'}`}
          >
            Profil Hotel
          </button>
          {currentUserRole === 'admin' && (
            <button 
              onClick={() => setActiveTab('accounts')}
              className={`flex-1 py-5 text-sm font-bold uppercase tracking-wider transition-all ${activeTab === 'accounts' ? 'bg-white text-indigo-600 border-b-2 border-indigo-600' : 'bg-slate-50 text-slate-400 hover:text-slate-600'}`}
            >
              Manajemen Akun
            </button>
          )}
        </div>

        {activeTab === 'profile' ? (
          <form onSubmit={handleSubmit} className="p-8 space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="col-span-full">
                <label className="block text-sm font-semibold text-slate-700 mb-2">Nama Hotel</label>
                <input
                  type="text"
                  value={formData.name}
                  onChange={(e) => setFormData({...formData, name: e.target.value})}
                  className="w-full px-4 py-3 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none transition-all font-bold"
                  required
                />
              </div>

              <div className="col-span-full">
                <label className="block text-sm font-semibold text-slate-700 mb-2">Alamat Lengkap</label>
                <textarea
                  value={formData.address}
                  onChange={(e) => setFormData({...formData, address: e.target.value})}
                  rows={2}
                  className="w-full px-4 py-3 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none transition-all"
                  required
                />
              </div>

              <div>
                <label className="block text-sm font-semibold text-slate-700 mb-2">Nomor Telepon</label>
                <input
                  type="text"
                  value={formData.phone}
