          </div>
        )}

        {viewMode === 'settings' && (
          <div className="flex-1 overflow-y-auto p-4 lg:p-6 animate-fade-in">
            <SettingsPage 
              settings={settings} 
              onSave={handleSaveSettings} 
              currentUserRole={userProfile?.role} 
