  const handleChangeRole = async (userId: string, newRole: UserRole) => {
    if (!confirm(`Ubah role pengguna ini menjadi ${newRole}?`)) return;
    const profile = profiles.find(p => p.id === userId);
    if (profile) {
      await upsertProfile({ ...profile, role: newRole });
      loadProfiles();
