      try {
        const publicUrl = await uploadAsset(file, formData, field);
        if (publicUrl) {
          const updatedData = { ...formData, [field]: publicUrl };
          if (field === 'logo') updatedData.stamp = publicUrl;
          setFormData(updatedData);
        }
