                      ? 'bg-indigo-600 border-indigo-600 scale-125' 
                      : 'bg-transparent border-slate-200'
                  }`}
                />
              ))}
            </div>

            <div className="grid grid-cols-3 gap-3">
              {[1, 2, 3, 4, 5, 6, 7, 8, 9, 'C', 0, '←'].map((key) => (
